  function customerFromSupabaseSession(session){
    const user=session?.user;if(!user)return null;
    const meta=user.user_metadata||{},previous=customerSession||{};
    const sameIdentity=previous.userId===user.id||Boolean(previous.email&&user.email&&previous.email.toLowerCase()===user.email.toLowerCase());
    return{userId:user.id,name:meta.full_name||meta.name||user.email?.split('@')[0]||'عميل NUVEXA HUB',phone:sameIdentity?(previous.phone||''):(user.phone||''),email:user.email||'',avatar:meta.avatar_url||meta.picture||'',provider:user.app_metadata?.provider||'oauth',signedAt:now()};
  }
