  function renderCommandResults(){const box=$('#commandResults'),q=$('#commandSearch')?.value||'';if(!box)return;const list=globalResults(q);box.innerHTML=list.length?list.map(r=>`<button class="command-item" data-open-module="${r.module}"><span class="ci">${r.icon}</span><span><strong>${esc(r.title)}</strong><small>${esc(r.kind)} · ${esc(r.meta)}</small></span></button>`).join(''):`<div class="empty" style="min-height:180px"><div><h3>${q?'لا توجد نتائج':'ابحث في كل النظام'}</h3><p>${q?'جرّب كلمة أخرى أو رقم فاتورة.':'اكتب اسم قسم أو عميل أو منتج أو رقم فاتورة.'}</p></div></div>`}
