  function statusBadge(status){const cls={مدفوعة:'b-green','تم التسليم':'b-green',معتمد:'b-green',مكتمل:'b-green',جديد:'b-gold','قيد التجهيز':'b-gold','جاهز للتوصيل':'b-blue','في الطريق':'b-purple',معلقة:'b-red','غير مدفوعة':'b-red','مدفوعة جزئيًا':'b-blue','بانتظار الاعتماد':'b-gold',مرفوضة:'b-red',ملغية:'b-red',مفتوحة:'b-red','تم الحل':'b-green'}[status]||'b-blue';return `<span class="badge ${cls}">${esc(status)}</span>`}
