  function fileToDataURL(file){return new Promise((resolve,reject)=>{if(!file)return resolve('');const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
  function optimizedImageDataURL(file,maxWidth=1280,maxHeight=900,quality=.82){return new Promise((resolve,reject)=>{if(!file)return resolve('');if(!file.type.startsWith('image/'))return reject(new Error('اختر ملف صورة صالح'));const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const img=new Image();img.onerror=reject;img.onload=()=>{let w=img.naturalWidth||img.width,h=img.naturalHeight||img.height;const ratio=Math.min(1,maxWidth/w,maxHeight/h);w=Math.max(1,Math.round(w*ratio));h=Math.max(1,Math.round(h*ratio));const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d');ctx.drawImage(img,0,0,w,h);resolve(canvas.toDataURL('image/webp',quality))};img.src=reader.result};reader.readAsDataURL(file)})}
  function whatsappConfigured(){return String(state.settings.whatsappNumber||'').replace(/\D/g,'').length>=8}
  function whatsappSetupBanner(){if(whatsappConfigured())return'';return `<section class="setup-warning"><div class="setup-warning-icon">!</div><div><strong>رقم استقبال طلبات واتساب غير مضاف</strong><p>أضف رقم التواصل من إعدادات المتجر حتى تصل طلبات العملاء مباشرة برسالة تحتوي على تفاصيل السلة.</p></div><button class="btn btn-gold" data-modal="settings">إضافة الرقم الآن</button></section>`}

  function activeSales(){return state.salesInvoices.filter(i=>i.approved!==false&&!['ملغية','مرفوضة'].includes(i.status))}
  function activePurchases(){return state.purchaseInvoices.filter(i=>i.approved!==false&&!['ملغية','مرفوضة'].includes(i.status))}
  function calculations(){
    const sales=activeSales(),purchases=activePurchases();
    const revenue=sales.reduce((s,i)=>s+num(i.total),0);
    const collected=sales.reduce((s,i)=>s+(i.payments||[]).reduce((a,p)=>a+num(p.amount),0),0);
    const receivables=sales.reduce((s,i)=>s+Math.max(0,num(i.total)-num(i.paid)),0);
    const cogs=sales.reduce((s,i)=>s+(i.items||[]).reduce((a,x)=>a+num(x.unitCost)*num(x.qty),0),0);
    const purchaseTotal=purchases.reduce((s,i)=>s+num(i.total),0);
    const purchasePaid=purchases.reduce((s,i)=>s+(i.payments||[]).reduce((a,p)=>a+num(p.amount),0),0);
    const supplierDebt=purchases.reduce((s,i)=>s+Math.max(0,num(i.total)-num(i.paid)),0);
    const expenses=state.expenses.filter(e=>e.status!=='ملغية').reduce((s,e)=>s+num(e.amount),0);
    let cash=num(state.accounts.openingCash),bank=num(state.accounts.openingBank);
    const apply=(method,amount,sign=1)=>{if(['نقدي','cash'].includes(method))cash+=sign*num(amount);else if(['تحويل بنكي','بطاقة','bank','card'].includes(method))bank+=sign*num(amount)};
    sales.forEach(i=>(i.payments||[]).forEach(p=>apply(p.method,p.amount,1)));
    purchases.forEach(i=>(i.payments||[]).forEach(p=>apply(p.method,p.amount,-1)));
    state.expenses.filter(e=>e.status!=='ملغية').forEach(e=>apply(e.method,e.amount,-1));
    state.finances.forEach(f=>{if(f.status==='ملغية')return;if(['تمويل مسترد','مساهمة غير مستردة','إيداع'].includes(f.type))apply(f.method,f.amount,1);if(['سداد تمويل','مسحوبات','سحب'].includes(f.type))apply(f.method,f.amount,-1);if(f.type==='تحويل خزنة إلى بنك'){cash-=num(f.amount);bank+=num(f.amount)}if(f.type==='تحويل بنك إلى خزنة'){bank-=num(f.amount);cash+=num(f.amount)}});
    const funds=cash+bank;
    const operatingProfit=revenue-cogs-expenses;
    const netAfterLiabilities=funds-supplierDebt;
    const coverage=supplierDebt>0?Math.min(100,Math.max(0,(funds/supplierDebt)*100)):100;
    return{revenue,collected,receivables,cogs,purchaseTotal,purchasePaid,supplierDebt,expenses,cash,bank,funds,operatingProfit,netAfterLiabilities,coverage};
  }
