  function showStore(){activeModule='';storeView='home';applyTheme();$('#storePage').classList.remove('hidden');$('#sellerPage')?.classList.add('hidden');$('#loginPage').classList.add('hidden');$('#adminGatePage').classList.add('hidden');$('#launcherPage').classList.add('hidden');$('#modulePage').classList.add('hidden');$('#quickFab')?.classList.add('hidden');$('#quickMenu')?.classList.add('hidden');renderStore()}

  let storeDismissedOfferId='';
  function storeOfferMeta(p){
    if(!p||p.archived||p.showInStore===false)return null;
    const current=num(p.price);
    const before=[p.originalPrice,p.oldPrice,p.compareAtPrice,p.regularPrice,p.priceBeforeDiscount,p.listPrice].map(num).find(v=>v>current);
    const corpus=`${p.name||''} ${p.shortDescription||''} ${p.description||''} ${p.specifications||''} ${p.offerText||''} ${p.offerLabel||''}`;
    const hasKeywords=/عرض|خصم|وفر|لفترة محدودة|sale|discount|offer/i.test(corpus);
    if(!before && !hasKeywords)return null;
    return {before,text:p.offerText||p.offerLabel||p.shortDescription||'عرض خاص لفترة محدودة'};
  }
  function getStoreOfferItem(list){
    return (list||[]).find(p=>p.id!==storeDismissedOfferId && storeOfferMeta(p));
  }

  function renderStore(){
    storeView='home';
    $('#storeCinematicHero')?.classList.remove('hidden');
    $$('.store-mobile-nav button').forEach(b=>b.classList.toggle('active',b.dataset.action==='store-home'));
    $('.store-about-entry')?.classList.remove('active');
    const list=storeProducts();
    const allVisible=state.products.filter(p=>!p.archived&&p.showInStore!==false);
    const latest=allVisible.slice().reverse();
    const physical=latest.filter(p=>p.type!=='digital');
    const digital=latest.filter(p=>p.type==='digital');
    const featured=latest.slice(0,4);
    const physicalCount=physical.length,digitalCount=digital.length;
    const cartTotal=storeCart.reduce((s,x)=>s+num(x.qty)*num(x.price),0);
    const card=(p,featuredCard=false)=>{
      const isDigital=p.type==='digital',available=isDigital||num(p.stock)>0;
      const stockLabel=isDigital?`حتى ${num(p.deviceLimit)||1} جهاز`:available?`متاح ${num(p.stock)}`:'نفد المخزون';
      return `<article id="store-product-${p.id}" class="store-product ${isDigital?'is-digital':'is-physical'}">
        <div class="store-product-media">
          <img src="${p.image||'assets/products/product-placeholder.webp'}" alt="${esc(p.name)}">
          <span class="store-type-badge">${isDigital?'خدمة رقمية':'منتج'}</span>
          ${featuredCard?'<span class="store-product-badge-left">مختار لك</span>':''}
        </div>
        <div class="store-product-body">
          <h3 title="${esc(p.name)}">${esc(p.name)}</h3>
          <p>${esc(p.shortDescription||p.description||p.size||'تفاصيل واضحة وسعر ظاهر قبل إتمام الطلب.')}</p>
          <div class="store-product-meta"><strong class="store-price"><small>السعر</small>${money(p.price)}</strong><span class="store-stock ${available?'':'out'}">${stockLabel}</span></div>
          <div class="store-product-actions"><button class="store-add" data-store-add="${p.id}" ${available?'':'disabled'}>${isDigital?'اختر الخدمة':'أضف للسلة'}</button><button class="store-view" data-store-view="${p.id}" aria-label="عرض التفاصيل">⌕</button></div>
        </div>
      </article>`
    };
    const emptyBlock=(title,text)=>`<div class="store-empty"><div><div style="font-size:43px">▦</div><h3>${esc(title)}</h3><p>${esc(text)}</p></div></div>`;
    const sectionGrid=(items,featuredCards=false)=>items.length?items.map(p=>card(p,featuredCards)).join(''):emptyBlock('لا توجد عناصر في هذا القسم','أضف العناصر من لوحة الإدارة وفعّل ظهورها في المتجر.');
    const isFocused=Boolean(storeSearch.trim()||storeFilter!=='all');
    const productCards=sectionGrid(list,false);
    const offerItem=getStoreOfferItem(allVisible),offerInfo=offerItem?storeOfferMeta(offerItem):null;
    const offerBanner=offerItem&&offerInfo?`<section class="store-offer-banner" aria-label="إعلان عرض">
      <div class="store-offer-copy">
        <span class="store-offer-kicker">✦ إعلان سريع</span>
        <h3>${esc(offerItem.name)}</h3>
        <p>${esc(offerInfo.text||'عرض خاص لفترة محدودة على أحد عناصر المتجر.')}</p>
        <div class="store-offer-actions">
          <span class="store-offer-price">السعر الحالي ${money(offerItem.price)} ${offerInfo.before?`<del>${money(offerInfo.before)}</del>`:''}</span>
          <button class="btn btn-gold" data-store-view="${offerItem.id}">عرض التفاصيل</button>
        </div>
      </div>
      <div class="store-offer-side">
        <button class="store-offer-close" type="button" title="إغلاق" data-dismiss-store-offer="${offerItem.id}">✕</button>
      </div>
    </section>`:'';
    $('#storeContent').innerHTML=`
      ${offerBanner}
      <section class="store-category-cards" aria-label="تصفح الأقسام">
        <button class="store-category-card ${storeFilter==='physical'?'active':''}" data-store-filter="physical"><span class="store-category-icon">▣</span><span><strong>المنتجات</strong><small>${physicalCount} منتج متاح للطلب</small></span></button>
        <button class="store-category-card ${storeFilter==='digital'?'active':''}" data-store-filter="digital"><span class="store-category-icon">◈</span><span><strong>الخدمات الرقمية</strong><small>${digitalCount} خدمة وموقع رقمي</small></span></button>
      </section>

      <section id="storeProductsSection">
        <div class="store-section-head">
          <div><span class="store-section-kicker">منتجات وخدمات</span><h2>المنتجات والخدمات الرقمية</h2><p>كل ما تضيفه من لوحة الإدارة يظهر هنا تلقائيًا بنفس البيانات المحدثة.</p></div>
          <div class="store-toolbar"><div class="store-search"><span>⌕</span><input id="storeSearchInput" value="${esc(storeSearch)}" placeholder="ابحث عن منتج أو خدمة..."></div><button class="store-filter ${storeFilter==='all'?'active':''}" data-store-filter="all">الكل</button><button class="store-filter ${storeFilter==='physical'?'active':''}" data-store-filter="physical">المنتجات</button><button class="store-filter ${storeFilter==='digital'?'active':''}" data-store-filter="digital">الخدمات الرقمية</button></div>
        </div>
        <div class="store-catalog-layout">
          <div class="store-catalog-main"><div class="store-grid">${productCards}</div></div>
          <aside class="store-side-rail">
            <div class="store-side-card"><h3>ملخص السلة</h3><p>راجع قيمة مشترياتك قبل إتمام الطلب.</p><div class="store-side-cart-summary"><span>${storeCart.reduce((s,x)=>s+num(x.qty),0)} عنصر</span><strong>${money(cartTotal)}</strong></div><button class="store-cart-checkout" data-action="store-cart">عرض السلة</button></div>
            <div class="store-side-card store-whatsapp-card"><div class="store-whatsapp-icon">◉</div><h3>طلب عبر واتساب</h3><p>بعد تجهيز السلة ينشئ الموقع رسالة قصيرة بكل تفاصيل الطلب.</p><button class="btn btn-success" style="width:100%;margin-top:12px" data-action="store-checkout">إتمام الطلب</button></div>
            <div class="store-side-card"><h3>تسوّق بثقة</h3><div class="store-security-list"><span><b>✓</b> السعر ظاهر قبل الطلب</span><span><b>✓</b> حساب العميل يحفظ طلباته</span><span><b>✓</b> الترخيص الرقمي قابل للإدارة</span><span><b>✓</b> المراجعة قبل التسليم</span></div></div>
          </aside>
        </div>
      </section>

      <footer class="store-footer"><div class="store-footer-brand"><img src="assets/branding/logo-main.png" alt="الشعار"></div><div class="store-footer-copy">واجهة بيع حديثة مرتبطة مباشرة بلوحة الإدارة والمنتجات والطلبات.</div></footer>`;
    renderStoreHeader();renderStoreCart()
  }

  function initAboutReveal(){
    const items=$$('.about-reveal');
    if(!('IntersectionObserver' in window)){items.forEach(x=>x.classList.add('is-visible'));return}
    const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.12,rootMargin:'0px 0px -40px'});
    items.forEach((item,index)=>{item.style.setProperty('--reveal-delay',`${Math.min(index%6,5)*70}ms`);observer.observe(item)});
  }
