  let sellerView='dashboard',sellerWizardStep=1,sellerDraft={},sellerEditingId='',sellerPreviewMode=false;
  const sellerIdentity=()=>({email:normalizeEmail(customerSession?.email||platformAccess.email||''),name:customerSession?.name||platformAccess.display_name||'البائع',phone:customerSession?.phone||''});
  const sellerOwnSubmissions=()=>{const email=sellerIdentity().email;return (state.sellerSubmissions||[]).filter(x=>sellerPreviewMode||!email||normalizeEmail(x.sellerEmail)===email)};
  const sellerStatusClass=status=>status==='معتمد ومنشور'?'approved':status==='بانتظار المراجعة'?'pending':status==='يحتاج تعديلًا'?'edit':status==='مرفوض'?'rejected':'draft';
  function sellerStatusBadge(status){return `<span class="seller-status ${sellerStatusClass(status)}">${esc(status||'مسودة')}</span>`}
  function sellerModuleContext(){return {state:()=>state,customerSession:()=>customerSession,platformAccess:()=>platformAccess,normalizeEmail,money,isSeller:isPlatformSeller,toast,renderWizard:renderSellerWizard,resetWizard:()=>{sellerWizardStep=1;sellerEditingId='';sellerDraft={}}}}
  function showSellerPortal(view='dashboard',preview=false){sellerPreviewMode=preview||sellerPreviewMode;sellerView=view;if(window.NuvexaSeller)return window.NuvexaSeller.show(view,preview,sellerModuleContext());toast('تعذر تحميل موديول البائع','error')}
  function sellerSetView(view){sellerView=view;if(window.NuvexaSeller)return window.NuvexaSeller.setView(view,sellerModuleContext());sellerWizardStep=1;sellerEditingId='';sellerDraft={};renderSellerPortal()}
  function renderSellerPortal(){if(window.NuvexaSeller)return window.NuvexaSeller.render(sellerModuleContext());}
  function renderSellerDashboard(){
    const list=sellerOwnSubmissions(),pending=list.filter(x=>x.status==='بانتظار المراجعة').length,approved=list.filter(x=>x.status==='معتمد ومنشور').length,edit=list.filter(x=>x.status==='يحتاج تعديلًا').length,rejected=list.filter(x=>x.status==='مرفوض').length;
    const rows=list.slice().reverse().slice(0,6);
    return `<section class="seller-welcome"><div><h1>مرحبًا بك، ${esc(sellerIdentity().name)} 👋</h1><p>من هنا يمكنك إضافة منتجاتك، متابعة حالة المراجعة، واستلام ملاحظات الإدارة قبل النشر.</p><button class="btn btn-gold" style="margin-top:17px" data-action="seller-new">＋ إضافة منتج جديد</button></div><img src="assets/about/about-commerce.webp" alt="إدارة المنتجات على منصة NUVEXA HUB"></section>
    <section class="seller-stat-grid"><div class="seller-stat"><div><span>إجمالي المنتجات</span><strong>${list.length}</strong></div><i>▣</i></div><div class="seller-stat pending"><div><span>بانتظار المراجعة</span><strong>${pending}</strong></div><i>⌛</i></div><div class="seller-stat approved"><div><span>معتمدة ومنشورة</span><strong>${approved}</strong></div><i>✓</i></div><div class="seller-stat edit"><div><span>يحتاج تعديلًا</span><strong>${edit}</strong></div><i>✎</i></div><div class="seller-stat rejected"><div><span>مرفوضة</span><strong>${rejected}</strong></div><i>✕</i></div></section>
    <section class="seller-panel"><div class="seller-panel-head"><h2>آخر المنتجات</h2><button class="btn btn-gold btn-sm" data-action="seller-new">＋ إضافة منتج</button></div><div class="seller-panel-body">${rows.length?`<div class="seller-product-list">${rows.map(renderSellerProductRow).join('')}</div>`:`<div class="seller-empty"><div><i>▣</i><h3>لم تُرسل منتجات بعد</h3><p>ابدأ بإضافة منتج أو خدمة، واحفظها كمسودة أو أرسلها للمراجعة.</p><button class="btn btn-gold" style="margin-top:14px" data-action="seller-new">إضافة أول منتج</button></div></div>`}</div></section>`
  }
  function renderSellerProductRow(x){const net=num(x.price)*(1-num(x.commission)/100);return `<article class="seller-product-row"><img src="${x.image||'assets/products/product-placeholder.webp'}" alt=""><div><h3>${esc(x.name||'منتج بدون اسم')}</h3><p>${esc(x.type==='digital'?'خدمة رقمية':x.category||'منتج عادي')}${x.adminNote?` · ملاحظة: ${esc(x.adminNote)}`:''}</p></div><div class="seller-price">${money(x.price)}<small style="display:block;color:#7c8997;margin-top:4px">صافي ${money(net)}</small></div>${sellerStatusBadge(x.status)}<div class="seller-row-actions"><button class="btn btn-soft btn-sm" data-seller-edit="${x.id}">${x.status==='مسودة'||x.status==='يحتاج تعديلًا'?'تعديل':'عرض'}</button></div></article>`}
  function renderSellerProducts(view){let list=sellerOwnSubmissions();if(view==='drafts')list=list.filter(x=>x.status==='مسودة');return `<section class="seller-panel"><div class="seller-panel-head"><div><h2>${view==='drafts'?'المسودات':'منتجاتي'}</h2><p style="margin:5px 0 0;color:#748397">تابع حالة كل منتج وملاحظات الإدارة.</p></div><button class="btn btn-gold" data-action="seller-new">＋ إضافة منتج جديد</button></div><div class="seller-panel-body">${list.length?`<div class="seller-product-list">${list.slice().reverse().map(renderSellerProductRow).join('')}</div>`:`<div class="seller-empty"><div><i>▤</i><h3>لا توجد عناصر هنا</h3><p>المنتجات والمسودات التي تنشئها ستظهر في هذه الصفحة.</p></div></div>`}</div></section>`}
  function renderSellerMessages(){const notes=sellerOwnSubmissions().filter(x=>x.adminNote);return `<section class="seller-panel"><div class="seller-panel-head"><h2>الرسائل والملاحظات</h2></div><div class="seller-panel-body">${notes.length?`<div class="seller-product-list">${notes.slice().reverse().map(x=>`<article class="seller-product-row"><img src="${x.image||'assets/products/product-placeholder.webp'}"><div><h3>${esc(x.name)}</h3><p>${esc(x.adminNote)}</p></div><div></div>${sellerStatusBadge(x.status)}<button class="btn btn-soft btn-sm" data-seller-edit="${x.id}">فتح</button></article>`).join('')}</div>`:`<div class="seller-empty"><div><i>◌</i><h3>لا توجد ملاحظات جديدة</h3><p>ستظهر هنا رسائل الإدارة وطلبات تعديل المنتجات.</p></div></div>`}</div></section>`}
  function renderSellerAccount(){const i=sellerIdentity();return `<section class="seller-panel"><div class="seller-panel-head"><h2>حساب البائع</h2></div><div class="seller-panel-body"><div class="seller-form-grid"><label>الاسم<input value="${esc(i.name)}" disabled></label><label>البريد<input value="${esc(i.email||'سيظهر بعد تفعيل ربط الإيميلات')}" disabled></label><label>الهاتف<input value="${esc(i.phone)}" disabled></label><label>الدور<input value="بائع خارجي" disabled></label></div><div class="submission-cloud-note" style="margin-top:18px"><i>☁</i><div><strong>الربط السحابي مؤجل للمرحلة الأخيرة</strong><p>سيتم ربط الحساب والمنتجات وإشعارات الاعتماد مع Supabase بعد الانتهاء من التصميم النهائي.</p></div></div></div></section>`}
  function productCopyTokens(value){return String(value||'').split(/[،,\n]+/).map(x=>x.trim()).filter(Boolean)}
  function generateProductCopy({name,type,tone,audience,size}){
    const cleanName=String(name||'').trim();if(!cleanName)throw new Error('اكتب اسم المنتج أولًا');
    const digital=type==='digital',who=String(audience||'العملاء الباحثين عن حل عملي وموثوق').trim(),unit=String(size||'').trim();
    const toneLead={professional:'حل احترافي',friendly:'اختيار سهل وعملي',premium:'تجربة متطورة بعناية'}[tone]||'حل احترافي';
    const shortDescription=digital
      ?`${cleanName} — ${toneLead} يساعد ${who} على إنجاز أعمالهم بكفاءة ووضوح.`
      :`${cleanName}${unit?` (${unit})`:''} — جودة موثوقة واستخدام عملي يناسب ${who}.`;
    const description=digital
      ?`${cleanName} هو ${toneLead} صُمم لتبسيط العمل وتقديم تجربة استخدام واضحة من أول خطوة. يناسب ${who}، ويجمع بين سهولة الاستخدام والتنظيم والمرونة، مع إمكانية الوصول من الأجهزة الحديثة وفق متطلبات الخدمة.\n\nيمكن استخدامه لتقليل الوقت الضائع، تنظيم المهام، وتحسين تجربة العميل أو فريق العمل. يتم عرض تفاصيل التفعيل والتسليم بوضوح قبل إتمام الطلب، مع دعم ومتابعة عند الحاجة.`
      :`${cleanName}${unit?` بحجم ${unit}`:''} منتج تم اختياره ليقدم توازنًا بين الجودة وسهولة الاستخدام. يناسب ${who}، ويتميز بتجربة شراء واضحة ومعلومات دقيقة عن السعر والتوفر.\n\nيتم تجهيز الطلب بعناية، مع توضيح حالة المخزون وخيارات الاستلام أو التوصيل المتاحة. راجع المواصفات قبل الشراء للتأكد من ملاءمته لاحتياجك.`;
    const features=digital
      ?['واجهة واضحة وسهلة الاستخدام','يعمل على الأجهزة والمتصفحات الحديثة','إعداد سريع وخطوات تشغيل منظمة','دعم ومتابعة بعد الشراء','قابل للتوسع حسب احتياج العميل']
      :['جودة موثوقة للاستخدام اليومي','معلومات واضحة عن السعر والتوفر','تجهيز وتغليف بعناية','سهولة الطلب والمتابعة','دعم مباشر عند الحاجة'];
    const baseTags=digital?['خدمة رقمية','حلول أعمال','تقنية','أونلاين']:['منتج','جودة','متجر','طلب مباشر'];
    const nameTags=cleanName.split(/\s+/).filter(x=>x.length>2).slice(0,3);
    return {shortDescription:shortDescription.slice(0,160),description,specifications:features.join('\n'),tags:[...new Set([...nameTags,...baseTags])].slice(0,8)}
  }
  let mediaDraftItems=[];let mediaDraftRatio='1:1';let mediaPreviewMode='desktop';
  function modalProductForm(){return $('#modalForm')}
  function mediaAspectValue(){return mediaDraftRatio==='4:5'?'4 / 5':mediaDraftRatio==='16:9'?'16 / 9':'1 / 1'}
  async function fileToMediaDraft(file){if(!file?.type?.startsWith('image/'))throw new Error('اختر ملفات صور فقط');if(file.size>8*1024*1024)throw new Error('حجم الصورة الواحدة يجب ألا يتجاوز 8 ميجابايت');return{src:await optimizedImageDataURL(file,1400,1400,.82),name:file.name,size:file.size,rotation:0}}
  async function addMediaFiles(files){const incoming=[...files];if(mediaDraftItems.length+incoming.length>7)throw new Error('الحد الأقصى 7 صور');for(const file of incoming)mediaDraftItems.push(await fileToMediaDraft(file));renderMediaDraft();updateProductQualityAndPreview()}
  function renderMediaDraft(){const box=$('#mediaGalleryPreview');if(!box)return;box.innerHTML=mediaDraftItems.length?mediaDraftItems.map((item,index)=>`<article class="media-preview-card ${index===0?'main':''}"><img src="${item.src}" alt="${esc(item.name||'صورة المنتج')}" style="aspect-ratio:${mediaAspectValue()};transform:rotate(${item.rotation||0}deg)"><div class="media-card-actions"><button type="button" data-media-main="${index}">${index===0?'رئيسية ✓':'اجعلها رئيسية'}</button><button type="button" class="remove" data-media-remove="${index}">حذف</button></div></article>`).join(''):'<div class="muted" style="grid-column:1/-1;text-align:center;padding:14px">لم تُضف صورًا بعد.</div>'}
  function initializeProductMedia(product){mediaDraftItems=[];mediaDraftRatio=product?.mediaRatio||'1:1';const sources=[product?.image,...(Array.isArray(product?.galleryImages)?product.galleryImages:[])].filter(Boolean).filter((v,i,a)=>a.indexOf(v)===i);mediaDraftItems=sources.map((src,index)=>({src,name:index?'صورة معاينة':'الصورة الرئيسية',size:0,rotation:0})).slice(0,7);setTimeout(()=>{document.querySelectorAll('[data-media-ratio]').forEach(b=>b.classList.toggle('active',b.dataset.mediaRatio===mediaDraftRatio));renderMediaDraft();updateProductQualityAndPreview()},0)}
  function productQualitySnapshot(){const form=modalProductForm();if(!form)return{score:0,items:[]};const name=form.elements.name?.value.trim()||'',price=num(form.elements.price?.value),desc=form.elements.description?.value.trim()||'',short=form.elements.shortDescription?.value.trim()||'',tags=productCopyTokens(form.elements.tags?.value||''),type=form.elements.type?.value||'physical';const checks=[['اسم المنتج واضح',name.length>=3],['السعر محدد',price>0],['وصف مختصر موجود',short.length>=20],['الوصف التفصيلي مناسب',desc.length>=80],['صورة رئيسية مضافة',mediaDraftItems.length>0],['معرض صور مكتمل',mediaDraftItems.length>=3],['وسوم البحث مضافة',tags.length>=3],['بيانات الخدمة الرقمية',type!=='digital'||Boolean(form.elements.serviceUrl?.value.trim())]];return{score:Math.round(checks.filter(x=>x[1]).length/checks.length*100),items:checks}}
  function updateProductQualityAndPreview(){const snap=productQualitySnapshot(),score=$('#productQualityScore'),list=$('#productQualityList'),preview=$('#productLivePreview'),form=modalProductForm();if(score){score.style.setProperty('--score',snap.score+'%');score.querySelector('span').textContent=snap.score}if(list)list.innerHTML=snap.items.map(([label,ok])=>`<div class="quality-item ${ok?'ok':'warn'}"><span>${ok?'✓':'!'}</span><strong>${label}</strong></div>`).join('');if(preview&&form){const image=mediaDraftItems[0]?.src||'assets/products/product-placeholder.webp',name=form.elements.name?.value.trim()||'اسم المنتج',short=form.elements.shortDescription?.value.trim()||'سيظهر هنا وصف مختصر وواضح للمنتج.',price=num(form.elements.price?.value);preview.className=`product-live-preview device-${mediaPreviewMode==='store'?'desktop':mediaPreviewMode}`;preview.innerHTML=`<div class="product-live-preview-card"><img src="${image}" alt="${esc(name)}"><div><h4>${esc(name)}</h4><p>${esc(short)}</p><strong>${price?money(price):'أدخل السعر'}</strong></div></div>`}}
  function applyGeneratedProductCopy(){
    const form=$('#modalDialog form');if(!form)return;
    const name=form.elements.name?.value,type=form.elements.type?.value||'physical',tone=$('#aiProductTone')?.value||'professional',audience=$('#aiProductAudience')?.value||'',size=form.elements.size?.value||'';
    const status=$('#aiProductStatus');try{if(status){status.className='ai-copy-status';status.textContent='جارٍ تجهيز النص...'}const copy=generateProductCopy({name,type,tone,audience,size});form.elements.shortDescription.value=copy.shortDescription;form.elements.description.value=copy.description;form.elements.specifications.value=copy.specifications;if(form.elements.tags)form.elements.tags.value=copy.tags.join('، ');if(status){status.className='ai-copy-status success';status.textContent='تم إنشاء الوصف والمميزات والوسوم. راجع النص وعدّله قبل الحفظ.'}toast('تم توليد محتوى المنتج بنجاح')}catch(error){if(status){status.className='ai-copy-status error';status.textContent=error.message||'تعذر إنشاء النص'}toast(error.message||'تعذر إنشاء النص','error')}
  }
  function sellerDraftDefaults(){const i=sellerIdentity();return {id:'',name:'',type:'physical',category:'',shortDescription:'',description:'',image:'',gallery:[],price:0,commission:15,stock:0,deliveryInfo:'',sellerName:i.name,sellerEmail:i.email,phone:i.phone,whatsapp:i.phone,note:'',status:'مسودة',adminNote:'',createdAt:now(),updatedAt:now()}}
  function openSellerWizard(id=''){sellerView='new';window.NuvexaSeller?.setWizardView(sellerModuleContext());sellerWizardStep=1;sellerEditingId=id;const row=(state.sellerSubmissions||[]).find(x=>x.id===id);sellerDraft=Object.assign(sellerDraftDefaults(),row||{});showSellerPortal('new',sellerPreviewMode||isPlatformAdmin())}
  function captureSellerDraft(){const f=$('#sellerWizardForm');if(!f)return;const fd=new FormData(f);for(const [k,v] of fd.entries()){if(['price','commission','stock'].includes(k))sellerDraft[k]=num(v);else sellerDraft[k]=String(v)} }
  function sellerStepTitle(){return ['البيانات الأساسية','الصور والمحتوى','السعر والاتفاق','بيانات التواصل','المراجعة والإرسال'][sellerWizardStep-1]}
  function renderSellerWizard(){sellerDraft=Object.assign(sellerDraftDefaults(),sellerDraft||{});const d=sellerDraft;const steps=['البيانات الأساسية','الصور والمحتوى','السعر والاتفاق','بيانات التواصل','المراجعة والإرسال'];const stepper=`<div class="seller-stepper">${steps.map((s,i)=>`<div class="seller-step ${sellerWizardStep===i+1?'active':sellerWizardStep>i+1?'done':''}"><b>${i+1}</b><span>${s}</span></div>`).join('')}</div>`;let fields='';
    if(sellerWizardStep===1)fields=`<div class="seller-form-grid"><label class="wide">اسم المنتج أو الخدمة *<input name="name" value="${esc(d.name)}" required placeholder="اكتب اسمًا واضحًا"></label><div class="wide"><label style="margin-bottom:7px">نوع المنتج *</label><div class="seller-type-pick"><button type="button" class="${d.type!=='digital'?'active':''}" data-seller-type="physical">▣ منتج عادي</button><button type="button" class="${d.type==='digital'?'active':''}" data-seller-type="digital">◇ خدمة رقمية</button></div><input type="hidden" name="type" value="${esc(d.type)}"></div><label class="wide">التصنيف *<input name="category" value="${esc(d.category)}" required placeholder="مثال: إلكترونيات أو تصميم مواقع"></label><label>وصف مختصر *<textarea name="shortDescription" maxlength="160" required>${esc(d.shortDescription)}</textarea></label><label>وصف تفصيلي *<textarea name="description" maxlength="2000" required>${esc(d.description)}</textarea></label></div>`;
    if(sellerWizardStep===2)fields=`<div class="seller-form-grid"><label class="wide">الصورة الرئيسية<input id="sellerMainImageInput" type="file" accept="image/*"><div class="seller-image-drop">${d.image?`<img src="${d.image}" alt="معاينة">`:`<div><i>▧</i><h3>اختر صورة رئيسية واضحة</h3><p>يفضل خلفية نظيفة وصورة مربعة أو أفقية.</p></div>`}</div></label><label class="wide">صور إضافية<input id="sellerGalleryInput" type="file" accept="image/*" multiple>${d.gallery?.length?`<div class="seller-gallery">${d.gallery.map(x=>`<img src="${x}" alt="">`).join('')}</div>`:''}</label><label class="wide">محتوى إضافي أو مواصفات<textarea name="specifications" placeholder="اكتب كل ميزة في سطر مستقل">${esc(d.specifications||'')}</textarea></label></div>`;
    if(sellerWizardStep===3){const net=num(d.price)*(1-num(d.commission)/100);fields=`<div class="seller-form-grid"><label>سعر البيع المقترح *<input name="price" type="number" min="0" step="0.01" value="${num(d.price)}" required></label><label>نسبة المنصة %<input name="commission" type="number" min="0" max="100" step="0.01" value="${num(d.commission)}"></label><label>الكمية المتاحة<input name="stock" type="number" min="0" step="1" value="${num(d.stock)}"></label><label>تكلفة المنتج — اختيارية<input name="cost" type="number" min="0" step="0.01" value="${num(d.cost)}"></label><label class="wide">الشحن أو طريقة تسليم الخدمة<textarea name="deliveryInfo">${esc(d.deliveryInfo)}</textarea></label></div><div class="seller-finance-summary"><div><span>سعر البيع</span><strong>${money(d.price)}</strong></div><div><span>نسبة المنصة</span><strong>${num(d.commission)}%</strong></div><div><span>صافي البائع المتوقع</span><strong>${money(net)}</strong></div></div>`}
    if(sellerWizardStep===4)fields=`<div class="seller-form-grid"><label>اسم البائع أو النشاط *<input name="sellerName" value="${esc(d.sellerName)}" required></label><label>البريد الإلكتروني<input name="sellerEmail" type="email" value="${esc(d.sellerEmail)}" ${d.sellerEmail?'readonly':''}></label><label>الهاتف<input name="phone" value="${esc(d.phone)}"></label><label>واتساب<input name="whatsapp" value="${esc(d.whatsapp)}"></label><label class="wide">ملاحظات للإدارة<textarea name="note">${esc(d.note)}</textarea></label></div>`;
    if(sellerWizardStep===5){const net=num(d.price)*(1-num(d.commission)/100);fields=`<div class="seller-review"><img src="${d.image||'assets/products/product-placeholder.webp'}" alt=""><dl><div><dt>المنتج</dt><dd>${esc(d.name||'غير مكتمل')}</dd></div><div><dt>النوع</dt><dd>${d.type==='digital'?'خدمة رقمية':'منتج عادي'}</dd></div><div><dt>التصنيف</dt><dd>${esc(d.category||'—')}</dd></div><div><dt>البائع</dt><dd>${esc(d.sellerName||sellerIdentity().name)}</dd></div><div><dt>السعر</dt><dd>${money(d.price)}</dd></div><div><dt>صافي البائع</dt><dd>${money(net)}</dd></div></dl></div><div class="submission-cloud-note" style="margin-top:17px"><i>✓</i><div><strong>لن يظهر المنتج مباشرة</strong><p>بعد الإرسال ينتقل إلى لوحة الإدارة للمراجعة، ثم يتم اعتماده أو طلب تعديلات عليه.</p></div></div>`}
    return `<section class="seller-wizard">${stepper}<div class="seller-wizard-layout"><form id="sellerWizardForm" class="seller-form-card" onsubmit="return false"><h2>${sellerStepTitle()}</h2><p>الخطوة ${sellerWizardStep} من 5</p>${fields}</form><aside class="seller-guide-card"><div><h3>نصائح مهمة</h3><ul><li>اكتب معلومات دقيقة وواضحة.</li><li>استخدم صورًا أصلية بجودة مناسبة.</li><li>حدد سعرًا ونسبة اتفاق واضحة.</li><li>راجع البيانات قبل الإرسال.</li></ul></div><div class="seller-preview-card"><img src="${d.image||'assets/products/product-placeholder.webp'}"><div><h4>${esc(d.name||'معاينة المنتج')}</h4><p>${esc(d.shortDescription||'سيظهر الوصف المختصر هنا.')}</p><strong>${money(d.price)}</strong></div></div></aside></div><div class="seller-wizard-actions"><div class="right">${sellerWizardStep>1?'<button class="btn btn-soft" data-seller-step="back">السابق</button>':''}<button class="btn btn-soft" data-seller-save-draft>حفظ كمسودة</button></div><div class="left">${sellerWizardStep<5?'<button class="btn btn-gold" data-seller-step="next">التالي</button>':'<button class="btn btn-success" data-seller-submit>إرسال للمراجعة</button>'}</div></div></section>`
  }
  function persistSellerSubmission(status='مسودة'){captureSellerDraft();const current=(state.sellerSubmissions||[]).find(x=>x.id===sellerEditingId);const item=Object.assign({},sellerDraft,{id:current?.id||uid('SUB'),sellerEmail:normalizeEmail(sellerDraft.sellerEmail||sellerIdentity().email),status,createdAt:current?.createdAt||now(),updatedAt:now()});state.sellerSubmissions=state.sellerSubmissions||[];if(current)Object.assign(current,item);else state.sellerSubmissions.push(item);sellerEditingId=item.id;sellerDraft=item;save();return item}
  function renderSellerSubmissions(){const all=state.sellerSubmissions||[];let list=all;if(activeTab==='المعتمدة')list=all.filter(x=>x.status==='معتمد ومنشور');else if(activeTab==='تحتاج تعديل')list=all.filter(x=>x.status==='يحتاج تعديلًا');else if(activeTab==='المرفوضة')list=all.filter(x=>x.status==='مرفوض');else if(activeTab==='البائعون')return renderSellerDirectory();else list=all.filter(x=>['بانتظار المراجعة','مسودة'].includes(x.status));const pending=all.filter(x=>x.status==='بانتظار المراجعة').length,approved=all.filter(x=>x.status==='معتمد ومنشور').length,edit=all.filter(x=>x.status==='يحتاج تعديلًا').length,rejected=all.filter(x=>x.status==='مرفوض').length;const rows=list.map(x=>{const net=num(x.price)*(1-num(x.commission)/100);return `<tr><td><img class="submission-thumb" src="${x.image||'assets/products/product-placeholder.webp'}"></td><td><strong>${esc(x.name||'بدون اسم')}</strong><div class="muted">${esc(x.category||'')}</div></td><td><strong>${esc(x.sellerName||'بائع')}</strong><div class="muted">${esc(x.sellerEmail||'')}</div></td><td>${money(x.price)}</td><td>${num(x.commission)}%</td><td class="positive">${money(net)}</td><td>${sellerStatusBadge(x.status)}</td><td><div class="toolbar"><button class="btn btn-soft btn-sm" data-submission-view="${x.id}">عرض</button>${x.status!=='معتمد ومنشور'?`<button class="btn btn-success btn-sm" data-submission-action="approve" data-id="${x.id}">اعتماد</button><button class="btn btn-blue btn-sm" data-submission-action="edit" data-id="${x.id}">طلب تعديل</button><button class="btn btn-danger btn-sm" data-submission-action="reject" data-id="${x.id}">رفض</button>`:''}</div></td></tr>`}).join('');const cards=list.map(x=>`<article class="submission-mobile-card"><div class="submission-mobile-card-head"><img src="${x.image||'assets/products/product-placeholder.webp'}"><div><h3>${esc(x.name||'بدون اسم')}</h3><p>${esc(x.sellerName||'بائع')} · ${money(x.price)}</p></div>${sellerStatusBadge(x.status)}</div><div class="submission-actions"><button class="btn btn-soft btn-sm" data-submission-view="${x.id}">عرض</button>${x.status!=='معتمد ومنشور'?`<button class="btn btn-success btn-sm" data-submission-action="approve" data-id="${x.id}">اعتماد</button><button class="btn btn-blue btn-sm" data-submission-action="edit" data-id="${x.id}">تعديل</button><button class="btn btn-danger btn-sm" data-submission-action="reject" data-id="${x.id}">رفض</button>`:''}</div></article>`).join('');return `${pageHead('طلبات منتجات البائعين','مراجعة واعتماد المنتجات والخدمات المرسلة من البائعين قبل ظهورها في المتجر.',`<button class="btn btn-gold" data-action="seller-preview">معاينة لوحة البائع</button>`)}<div class="submission-cloud-note"><i>☁</i><div><strong>التصميم جاهز والربط السحابي مؤجل</strong><p>ستنتقل هذه البيانات إلى Supabase بعد اعتماد التصميم النهائي وتشغيل نظام أدوار الإيميلات.</p></div></div><div class="stat-grid" style="margin-bottom:16px"><div class="stat"><div><span>كل الطلبات</span><strong>${all.length}</strong></div><div class="ico">▣</div></div><div class="stat"><div><span>بانتظار المراجعة</span><strong>${pending}</strong></div><div class="ico">⌛</div></div><div class="stat"><div><span>معتمدة</span><strong>${approved}</strong></div><div class="ico">✓</div></div><div class="stat"><div><span>تحتاج إجراء</span><strong>${edit+rejected}</strong></div><div class="ico">!</div></div></div><section class="panel"><div class="panel-head"><h3>${esc(activeTab)}</h3><span class="badge b-blue">${list.length}</span></div><div class="panel-body">${list.length?`<div class="submission-table-wrap table-wrap"><table class="table"><thead><tr><th>الصورة</th><th>المنتج</th><th>البائع</th><th>السعر</th><th>نسبة المنصة</th><th>صافي البائع</th><th>الحالة</th><th>الإجراءات</th></tr></thead><tbody>${rows}</tbody></table></div><div class="submission-card-list">${cards}</div>`:empty('assets/empty-states/empty-orders.webp','لا توجد طلبات في هذه الحالة','ستظهر منتجات البائعين هنا بعد إرسالها للمراجعة.')}</div></section>`}
  function renderSellerDirectory(){const emails=[...new Set((state.sellerSubmissions||[]).map(x=>normalizeEmail(x.sellerEmail)).filter(Boolean))];return `${pageHead('البائعون','ملخص البائعين الذين أرسلوا منتجات للمنصة.')}<section class="panel"><div class="panel-body">${emails.length?`<div class="table-wrap"><table class="table"><thead><tr><th>البريد</th><th>عدد المنتجات</th><th>المعتمد</th><th>بانتظار المراجعة</th></tr></thead><tbody>${emails.map(email=>{const list=state.sellerSubmissions.filter(x=>normalizeEmail(x.sellerEmail)===email);return `<tr><td><strong>${esc(email)}</strong></td><td>${list.length}</td><td>${list.filter(x=>x.status==='معتمد ومنشور').length}</td><td>${list.filter(x=>x.status==='بانتظار المراجعة').length}</td></tr>`}).join('')}</tbody></table></div>`:empty('assets/empty-states/empty-customers.webp','لا يوجد بائعون بعد','سيظهر البائع بعد تسجيله وإرسال أول منتج.')}</div></section>`}
  function viewSellerSubmission(id){const x=(state.sellerSubmissions||[]).find(i=>i.id===id);if(!x)return;modalType='seller-submission-view';$('#modalSave').classList.add('hidden');$('#modalTitle').textContent='تفاصيل طلب المنتج';$('#modalBody').innerHTML=`<div class="seller-review"><img src="${x.image||'assets/products/product-placeholder.webp'}"><dl><div><dt>المنتج</dt><dd>${esc(x.name)}</dd></div><div><dt>البائع</dt><dd>${esc(x.sellerName||'—')}</dd></div><div><dt>البريد</dt><dd>${esc(x.sellerEmail||'—')}</dd></div><div><dt>الحالة</dt><dd>${esc(x.status)}</dd></div><div><dt>السعر</dt><dd>${money(x.price)}</dd></div><div><dt>نسبة المنصة</dt><dd>${num(x.commission)}%</dd></div><div><dt>الوصف</dt><dd>${esc(x.description||x.shortDescription||'—')}</dd></div><div><dt>ملاحظات البائع</dt><dd>${esc(x.note||'—')}</dd></div>${x.adminNote?`<div><dt>ملاحظة الإدارة</dt><dd>${esc(x.adminNote)}</dd></div>`:''}</dl></div>`;$('#modalDialog').showModal()}
  function reviewSellerSubmission(id,action){const x=(state.sellerSubmissions||[]).find(i=>i.id===id);if(!x)return;if(action==='approve'){x.status='معتمد ومنشور';x.adminNote='تم الاعتماد والنشر';if(!x.productId){const p={id:uid('PRD'),name:x.name,type:x.type||'physical',category:x.category||'',shortDescription:x.shortDescription||'',description:x.description||'',specifications:x.specifications||'',image:x.image||'assets/products/product-placeholder.webp',galleryImages:x.gallery||[],price:num(x.price),cost:num(x.cost),stock:x.type==='digital'?0:num(x.stock),showInStore:true,allowSiteOrder:true,allowWhatsApp:true,deviceLimit:1,serviceUrl:'',archived:false,sourceSellerEmail:x.sellerEmail};state.products.push(p);x.productId=p.id}}else{const note=prompt(action==='edit'?'اكتب التعديل المطلوب من البائع:':'اكتب سبب الرفض:','');if(note===null)return;x.status=action==='edit'?'يحتاج تعديلًا':'مرفوض';x.adminNote=note.trim()|| (action==='edit'?'يرجى مراجعة البيانات وإعادة الإرسال':'تم رفض الطلب')}x.updatedAt=now();audit(action==='approve'?'اعتماد منتج بائع':action==='edit'?'طلب تعديل منتج بائع':'رفض منتج بائع',x.name);save();renderModule('seller-submissions');toast(action==='approve'?'تم اعتماد المنتج ونشره':action==='edit'?'تم إرسال طلب التعديل':'تم رفض الطلب')}

  function addStoreCart(id){const p=state.products.find(x=>x.id===id);if(!p||p.archived||p.showInStore===false)return;if(p.type!=='digital'&&num(p.stock)<=0){toast('المنتج غير متاح حاليًا','error');return}const item=storeCart.find(x=>x.productId===id);if(item){if(p.type!=='digital'&&item.qty>=num(p.stock)){toast('وصلت للكمية المتاحة','error');return}item.qty++}else storeCart.push({productId:p.id,name:p.name,qty:1,price:num(p.price),image:p.image||'assets/products/product-placeholder.webp',nonStock:p.type==='digital',type:p.type||'physical',deviceLimit:num(p.deviceLimit)||1});saveStoreCart();toast('تمت إضافة المنتج إلى السلة')}
  function renderStoreCart(){const box=$('#storeCartItems'),totalEl=$('#storeCartTotal');if(!box||!totalEl)return;const total=storeCart.reduce((s,x)=>s+num(x.qty)*num(x.price),0);totalEl.textContent=money(total);box.innerHTML=storeCart.length?storeCart.map(x=>`<div class="store-cart-item"><img src="${x.image}" alt=""><div><strong>${esc(x.name)}</strong><small>${money(x.price)} · ${x.nonStock?'رقمي':'منتج عادي'}</small><div class="store-qty"><button data-store-cart-dec="${x.productId}">−</button><b>${x.qty}</b><button data-store-cart-inc="${x.productId}">＋</button></div></div><button class="btn btn-danger btn-sm" data-store-cart-remove="${x.productId}">حذف</button></div>`).join(''):`<div class="store-empty" style="padding:35px 12px"><div style="font-size:45px">🛒</div><h3>السلة فارغة</h3><p>أضف منتجًا أو خدمة للمتابعة.</p></div>`;renderStoreHeader()}
  function toggleStoreCart(open=true){$('#storeCartDrawer').classList.toggle('open',open);$('#storeOverlay').classList.toggle('show',open);if(open)renderStoreCart()}
  function viewStoreProduct(id){const p=state.products.find(x=>x.id===id);if(!p)return;const digital=p.type==='digital',gallery=[p.image||'assets/products/product-placeholder.webp',...(Array.isArray(p.galleryImages)?p.galleryImages:[])],features=String(p.specifications||'').split(/\n+/).map(x=>x.trim()).filter(Boolean);$('#storeProductDialogContent').innerHTML=`<div class="store-dialog-head"><h3>تفاصيل المنتج</h3><button data-action="close-store-product">✕</button></div><div class="store-dialog-body play-detail-body"><section class="play-detail-hero"><img class="play-detail-icon" src="${p.image||'assets/products/product-placeholder.webp'}" alt=""><div class="play-detail-title"><span class="store-type-badge" style="position:static;display:inline-block">${digital?'موقع / خدمة رقمية':'منتج عادي'}</span><h2>${esc(p.name)}</h2><p>${esc(p.shortDescription||p.description||'تفاصيل واضحة قبل إتمام الطلب.')}</p><div class="play-detail-meta"><span>★ منتج موثوق</span><span>${digital?`حتى ${num(p.deviceLimit)||1} جهاز`:`المتاح ${num(p.stock)}`}</span><strong>${money(p.price)}</strong></div></div><button class="store-cart-checkout play-buy-button" data-store-add="${p.id}">أضف للسلة</button></section>${gallery.length?`<section class="play-detail-section"><div class="play-detail-section-head"><h3>صور المعاينة</h3><small>${gallery.length} صورة</small></div><img id="storeProductMainPreview" class="play-main-preview" src="${gallery[0]}" alt="معاينة المنتج"><div class="play-screenshot-strip">${gallery.map((src,index)=>`<button type="button" class="play-shot ${index===0?'active':''}" data-product-preview-id="${p.id}" data-product-preview-index="${index}"><img src="${src}" alt="معاينة ${index+1}"></button>`).join('')}</div></section>`:''}<section class="play-detail-section"><h3>حول هذا المنتج</h3><p class="play-long-description">${esc(p.description||p.shortDescription||'لا يوجد وصف إضافي.')}</p></section>${features.length?`<section class="play-detail-section"><h3>المميزات والمواصفات</h3><ul class="play-feature-list">${features.map(x=>`<li><span>✓</span>${esc(x)}</li>`).join('')}</ul></section>`:''}<section class="play-info-grid">${p.developerName?`<div><span>مقدم الخدمة</span><strong>${esc(p.developerName)}</strong></div>`:''}${p.versionLabel?`<div><span>الإصدار</span><strong>${esc(p.versionLabel)}</strong></div>`:''}${p.compatibility?`<div><span>التوافق</span><strong>${esc(p.compatibility)}</strong></div>`:''}<div><span>نوع المنتج</span><strong>${digital?'خدمة تعمل أونلاين':'منتج متاح للطلب'}</strong></div></section></div>`;$('#storeProductDialog').showModal()}
  function openCustomerAuth(after=null,intent='account'){pendingCustomerAction=after;pendingCustomerIntent=intent;$('#customerLocalLoginPanel')?.classList.add('hidden');const toggle=$('[data-action="toggle-local-login"]');if(toggle)toggle.textContent='الدخول بالاسم ورقم الهاتف';if(!$('#customerAuthDialog').open)$('#customerAuthDialog').showModal()}
  function openCustomerPhoneCompletion(after=null,intent='checkout'){pendingCustomerAction=after;pendingCustomerIntent=intent;const input=$('#customerPhoneInput');if(input)input.value=customerSession?.phone||'';if(!$('#customerPhoneDialog').open)$('#customerPhoneDialog').showModal();setTimeout(()=>input?.focus(),60)}
  function ensureCustomer(action,intent='account',requirePhone=false){if(customerSession){if(requirePhone&&!String(customerSession.phone||'').trim()){openCustomerPhoneCompletion(action,intent);return}action();return}openCustomerAuth(action,intent)}
  function checkoutStepMarkup(step=1){return `<div class="checkout-steps"><div class="checkout-step ${step===1?'active':step>1?'done':''}"><b>${step>1?'✓':'1'}</b><span>بيانات الطلب</span></div><div class="checkout-step ${step===2?'active':step>2?'done':''}"><b>${step>2?'✓':'2'}</b><span>طريقة الدفع</span></div><div class="checkout-step ${step===3?'active':''}"><b>3</b><span>المراجعة</span></div></div>`}
  function setStoreCheckoutStep(step){const dialog=$('#storeCheckoutDialogContent');if(!dialog)return;dialog.dataset.checkoutStep=String(step);dialog.querySelector('.checkout-steps')?.replaceWith((()=>{const box=document.createElement('div');box.innerHTML=checkoutStepMarkup(step);return box.firstElementChild})());dialog.querySelectorAll('.checkout-pane').forEach(x=>x.classList.toggle('active',Number(x.dataset.checkoutPane)===step));const back=dialog.querySelector('[data-checkout-back]'),next=dialog.querySelector('[data-checkout-next]'),submit=dialog.querySelector('[data-store-order="site"]');if(back)back.classList.toggle('hidden',step===1);if(next)next.classList.toggle('hidden',step===3);if(submit)submit.classList.toggle('hidden',step!==3)}
  function openStoreCheckout(){if(!storeCart.length){toast('السلة فارغة','error');return}ensureCustomer(()=>{toggleStoreCart(false);const needsAddress=storeCart.some(x=>!x.nonStock),subtotal=storeCart.reduce((s,x)=>s+num(x.qty)*num(x.price),0),delivery=needsAddress?0:0,total=subtotal+delivery,siteAllowed=storeCart.every(x=>state.products.find(p=>p.id===x.productId)?.allowSiteOrder!==false),whatsappAllowed=whatsappConfigured()&&storeCart.every(x=>state.products.find(p=>p.id===x.productId)?.allowWhatsApp!==false);$('#storeCheckoutDialogContent').innerHTML=`<div class="store-dialog-head"><h3>إتمام الطلب</h3><button data-action="close-store-checkout">✕</button></div><div class="store-dialog-body">${checkoutStepMarkup(1)}<section class="checkout-pane active" data-checkout-pane="1"><div class="panel" style="padding:13px;margin-bottom:14px"><div class="total-line"><span>العميل</span><strong>${esc(customerSession.name)}</strong></div><div class="total-line"><span>الهاتف</span><strong>${esc(customerSession.phone||'—')}</strong></div></div><div class="form-grid"><div class="field wide"><label>عنوان التوصيل ${needsAddress?'':'— اختياري للمنتجات الرقمية'}</label><input id="storeOrderAddress" ${needsAddress?'required':''} placeholder="اكتب العنوان بالتفصيل"></div><div class="field wide"><label>ملاحظات الطلب</label><textarea id="storeOrderNotes" placeholder="أي ملاحظات خاصة بالتوصيل أو التنفيذ"></textarea></div></div></section><section class="checkout-pane" data-checkout-pane="2"><h3 style="margin-top:0">اختر طريقة الدفع</h3><div class="checkout-payment-grid"><button class="checkout-payment active" data-checkout-payment="cash">💵<br>الدفع عند الاستلام</button><button class="checkout-payment" data-checkout-payment="bank">🏦<br>تحويل بنكي</button></div><input type="hidden" id="storePaymentMethod" value="cash"><div id="storePaymentNote" class="checkout-warning" style="margin-top:12px">سيتم تأكيد الطلب والتواصل معك قبل التنفيذ.</div></section><section class="checkout-pane" data-checkout-pane="3"><h3 style="margin-top:0">راجع طلبك</h3><div class="checkout-order-items">${storeCart.map(x=>`<div class="checkout-order-item"><img src="${x.image}" alt=""><div><strong>${esc(x.name)}</strong><small>${x.qty} × ${money(x.price)}</small></div><b>${money(x.qty*x.price)}</b></div>`).join('')}</div><div class="checkout-summary"><div class="total-line"><span>الإجمالي الفرعي</span><strong>${money(subtotal)}</strong></div><div class="total-line"><span>التوصيل</span><strong>${delivery?money(delivery):'يحدد لاحقًا'}</strong></div><div class="total-line grand"><span>الإجمالي</span><strong>${money(total)}</strong></div></div>${!siteAllowed?'<p class="checkout-warning">الطلب داخل المنصة غير متاح لأحد المنتجات.</p>':''}</section><div class="checkout-nav"><button class="btn btn-soft hidden" data-checkout-back>السابق</button><span></span><button class="btn btn-gold" data-checkout-next>التالي</button><button class="btn btn-success hidden" data-store-order="site" ${siteAllowed?'':'disabled'}>تأكيد الطلب</button></div>${whatsappAllowed?'<button class="btn btn-soft" style="width:100%;margin-top:9px" data-store-order="whatsapp">إرسال نسخة عبر واتساب</button>':''}</div>`;$('#storeCheckoutDialog').showModal()},'checkout',true)}
  function findStoreCustomer(){if(!customerSession)return null;return state.customers.find(x=>(customerSession.userId&&x.authUserId===customerSession.userId)||(customerSession.phone&&x.phone===customerSession.phone)||(customerSession.email&&x.email&&x.email.toLowerCase()===customerSession.email.toLowerCase()))||null}
  function getOrCreateStoreCustomer(){const phone=String(customerSession.phone||'').trim();let c=findStoreCustomer();if(!c){c={id:uid('CUS'),authUserId:customerSession.userId||'',authProvider:customerSession.provider||'local',name:customerSession.name,phone,whatsapp:phone,email:customerSession.email||'',avatar:customerSession.avatar||'',classification:'جديد',creditLimit:0,address:$('#storeOrderAddress')?.value||'',notes:'عميل من المتجر',followups:[],archived:false};state.customers.push(c)}else{c.authUserId=customerSession.userId||c.authUserId||'';c.authProvider=customerSession.provider||c.authProvider||'local';c.name=customerSession.name;c.phone=phone||c.phone;c.whatsapp=phone||c.whatsapp;c.email=customerSession.email||c.email;c.avatar=customerSession.avatar||c.avatar;c.address=$('#storeOrderAddress')?.value||c.address}return c}
  function storeOrderMessage(){const total=storeCart.reduce((s,x)=>s+num(x.qty)*num(x.price),0);return `مرحبًا، أريد تنفيذ الطلب التالي:\n${storeCart.map(x=>`• ${x.name} × ${x.qty} = ${money(x.qty*x.price)}`).join('\n')}\n\nالإجمالي: ${money(total)}\nالاسم: ${customerSession.name}\nالهاتف: ${customerSession.phone}\nالعنوان: ${$('#storeOrderAddress')?.value||'غير مطلوب'}\nملاحظات: ${$('#storeOrderNotes')?.value||'لا توجد'}`}
  async function submitStoreOrder(mode){
    if(!customerSession||!storeCart.length)return;
    if(mode==='site'&&!storeCart.every(x=>state.products.find(p=>p.id===x.productId)?.allowSiteOrder!==false)){toast('الطلب داخل المنصة غير متاح لأحد المنتجات','error');return}
    if(mode==='whatsapp'){const message=storeOrderMessage(),phone=String(state.settings.whatsappNumber||'').replace(/\D/g,'');if(!phone){toast('الطلب عبر واتساب غير مفعّل حاليًا.','error');return}window.open(`https://wa.me/${phone}?text=${encodeURIComponent(message)}`,'_blank','noopener');return}
    try{
      const result=await createCloudStoreOrder();
      const number=`ORD-${result?.order_number||''}`;
      storeCart=[];saveStoreCart();
      $('#storeCheckoutDialogContent').innerHTML=`<div class="store-dialog-head"><h3>تم استلام الطلب</h3><button data-action="close-store-checkout">✕</button></div><div class="store-dialog-body checkout-success"><i>✓</i><h2>طلبك اتسجل بنجاح</h2><p>تم حفظ الطلب والفاتورة في حسابك السحابي.</p><span class="checkout-order-number">${esc(number)}</span><div style="margin-top:16px"><button class="btn btn-gold" data-action="close-store-checkout">العودة للمتجر</button></div></div>`;
      toast(`تم تسجيل الطلب ${number}`);renderStore();
    }catch(error){toast(error?.message||'تعذر تسجيل الطلب','error')}
  }
  function showCustomerAccount(){ensureCustomer(()=>{const c=findStoreCustomer(),orders=c?state.orders.filter(o=>o.customerId===c.id):[],licenses=c?state.licenses.filter(l=>l.customerId===c.id):[],avatar=customerSession.avatar?`<img class="customer-account-avatar" src="${esc(customerSession.avatar)}" alt="" referrerpolicy="no-referrer">`:'<div class="customer-account-fallback">👤</div>',identity=[customerSession.email,customerSession.phone].filter(Boolean);$('#customerAccountDialogContent').innerHTML=`<div class="store-dialog-head"><h3>حسابي</h3><button data-action="close-customer-account">✕</button></div><div class="store-dialog-body"><div class="customer-account-head">${avatar}<div><strong>${esc(customerSession.name)}</strong><div class="customer-account-meta">${identity.length?identity.map(x=>`<span>${esc(x)}</span>`).join(''):`<span>الدخول عبر ${esc(customerProviderLabel(customerSession.provider))}</span>`}</div></div><button class="btn btn-soft btn-sm" data-action="customer-logout">تسجيل الخروج</button></div><h3>طلباتي</h3>${orders.length?orders.map(o=>`<div class="total-line"><span>${esc(o.number)} · ${esc(o.status)}</span><strong>${money(o.total)}</strong></div>`).join(''):`<p style="color:#86715f">لا توجد طلبات مسجلة.</p>`}<h3 style="margin-top:22px">مشترياتي الرقمية</h3>${licenses.length?licenses.map(l=>`<div class="total-line"><span>${esc(productName(l.productId))}<small style="display:block;color:#86715f">${l.devices.length}/${l.deviceLimit} جهاز</small></span><span class="license-key">${esc(l.key)}</span></div>`).join(''):`<p style="color:#86715f">ستظهر التراخيص هنا بعد تسليم الطلب الرقمي.</p>`}</div>`;$('#customerAccountDialog').showModal()},'account',false)}
