  function renderLicenseDevices(){const rows=(state.licenses||[]).flatMap(l=>(l.devices||[]).map(d=>({license:l,device:d})));return `${pageHead('الأجهزة المرتبطة','حذف جهاز محدد أو تسجيل الخروج من جميع أجهزة العميل.')}<section class="panel"><div class="panel-body">${rows.length?`<div class="table-wrap"><table class="table"><thead><tr><th>العميل</th><th>المنتج</th><th>الجهاز</th><th>Device ID</th><th>آخر نشاط</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>${rows.map(({license:l,device:d})=>`<tr><td>${esc(licenseClientLabel(l))}</td><td>${esc(licenseProductLabel(l))}</td><td><strong>${esc(d.name||'جهاز')}</strong><div class="muted">${esc(d.platform||d.ip||'')}</div></td><td><span class="license-code">${esc(d.deviceId||d.id)}</span></td><td>${fmtDate(d.lastSeenAt)}</td><td>${statusBadge(d.active===false?'غير نشط':'نشط')}</td><td><button class="btn btn-danger btn-sm" data-license-device-remove="${l.id}" data-device-id="${d.id}">حذف الجهاز</button></td></tr>`).join('')}</tbody></table></div>`:empty('assets/empty-states/empty-notifications.webp','لا توجد أجهزة مرتبطة','ستظهر الأجهزة عند ربط المواقع أو إضافتها يدويًا.')}</div></section>`}
