  function renderLauncher(){
    $('#launcherContent').className=`launcher-content view-${launcherView}`;
    const c=calculations(),q=($('#globalSearch')?.value||'').trim().toLowerCase();
    const allowed=MODULES.filter(m=>!m.restricted||canViewAccounts());
    const modules=allowed.filter(m=>!q||`${m.name} ${m.desc}`.toLowerCase().includes(q));
    const fav=favoriteIds().map(id=>allowed.find(m=>m.id===id)).filter(Boolean);
    const recent=recentIds().map(id=>allowed.find(m=>m.id===id)).filter(Boolean).slice(0,6);
    const appTile=m=>`<article class="app-tile">${moduleCount(m.id)?`<span class="tile-count">${moduleCount(m.id)}</span>`:''}<button class="fav-btn ${favoriteIds().includes(m.id)?'active':''}" data-favorite-module="${m.id}" title="المفضلة">${favoriteIds().includes(m.id)?'★':'☆'}</button><button class="app-open" data-open-module="${m.id}"><div class="app-icon">${m.asset?`<img src="${assetSrc(m.asset)}" alt="${esc(m.name)}" onerror="this.style.display='none';this.nextElementSibling.style.display='inline'"><span class="emoji" style="display:none">${m.emoji}</span>`:`<span class="emoji">${m.emoji}</span>`}</div><strong>${esc(m.name)}</strong><small>${esc(m.desc)}</small></button></article>`;
    const results=q?globalResults(q):[];
    $('#launcherContent').innerHTML=`
      <section class="launcher-hero v6-hero"><div class="content"><span class="badge b-gold">NUVEXA HUB V10.0</span><h1>أهلًا بك في لوحة التحكم 👋</h1><p>إدارة أبسط، أرقام أدق، وكل قسم يفتح داخل نفس الواجهة بدون الانتقال بين المتصفح والتطبيق.</p><div class="hero-actions"><button class="btn btn-gold" data-action="quick-actions">＋ إجراء سريع</button><button class="btn btn-soft" data-action="command">⌕ بحث شامل <small>Ctrl+K</small></button></div><div class="hero-mini"><div><span>إجمالي المبيعات</span><strong>${money(c.revenue)}</strong></div><div><span>الطلبات المفتوحة</span><strong>${state.orders.filter(o=>!['تم التسليم','ملغية'].includes(o.status)).length}</strong></div><div><span>التنبيهات</span><strong>${moduleCount('alerts')}</strong></div><div><span>صافي المركز</span><strong class="${c.netAfterLiabilities<0?'negative':'positive'}">${money(c.netAfterLiabilities)}</strong></div></div></div><div class="photo"></div></section>
      ${whatsappSetupBanner()}
      ${q?`<section class="apps-section"><div class="apps-section-title"><div><h2>نتائج البحث</h2><p>نتائج من الأقسام والبيانات المسجلة</p></div><span class="badge b-gold">${results.length} نتيجة</span></div>${results.length?`<div class="search-results">${results.map(r=>`<button class="search-result" data-open-module="${r.module}"><span class="result-ico">${r.icon}</span><span><strong>${esc(r.title)}</strong><small>${esc(r.kind)} · ${esc(r.meta)}</small></span></button>`).join('')}</div>`:`<div class="panel"><div class="empty" style="min-height:180px"><div><h3>لا توجد نتائج</h3><p>جرّب اسمًا أو رقم هاتف أو رقم فاتورة آخر.</p></div></div></div>`}</section>`:''}
      ${!q&&fav.length?`<section class="apps-section"><div class="apps-section-title"><div><h2>المفضلة</h2><p>الأقسام التي تستخدمها أكثر</p></div></div><div class="apps-grid">${fav.map(appTile).join('')}</div></section>`:''}
      ${!q&&recent.length?`<section class="apps-section"><div class="apps-section-title"><div><h2>استخدمتها مؤخرًا</h2><p>عودة سريعة لآخر الأقسام</p></div></div><div class="apps-grid">${recent.map(appTile).join('')}</div></section>`:''}
      <section class="apps-section"><div class="apps-section-title"><div><h2>${q?'التطبيقات المطابقة':'أقسام لوحة الإدارة'}</h2><p>كل وظيفة موجودة داخل قسمها الطبيعي، مع الحفاظ على جميع الخصائص الحالية.</p></div><div class="launcher-view-switch" aria-label="طريقة عرض الأقسام"><button class="view-switch-btn ${launcherView==='cards'?'active':''}" data-launcher-view="cards" title="بطاقات">▦</button><button class="view-switch-btn ${launcherView==='compact'?'active':''}" data-launcher-view="compact" title="أيقونات مدمجة">▥</button><button class="view-switch-btn ${launcherView==='list'?'active':''}" data-launcher-view="list" title="قائمة">☰</button><button class="btn btn-soft" data-action="refresh">↻ تحديث</button></div></div>
      ${q?`<div class="apps-grid">${modules.map(appTile).join('')}</div>`:MODULE_GROUPS.map(g=>{const list=g.modules.map(id=>allowed.find(m=>m.id===id)).filter(Boolean);return list.length?`<section class="apps-group"><div class="apps-group-head"><div><h3>${esc(g.name)}</h3><p>${esc(g.desc)}</p></div><span class="badge b-blue">${list.length}</span></div><div class="apps-grid">${list.map(appTile).join('')}</div></section>`:''}).join('')}
      </section>`;
  }
  function pageHead(title,desc,actions=''){return `<div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div><div class="page-actions">${actions}</div></div>`}
  function stat(label,value,ico,sub=''){return `<div class="stat"><div><span>${esc(label)}</span><strong class="number">${typeof value==='number'?money(value):value}</strong><small>${esc(sub)}</small></div><div class="ico">${ico}</div></div>`}
  function renderSidebar(module){return window.NuvexaAdmin?.renderSidebar(buildAdminContext(),module)}
  function buildOrdersContext(){return {state,pageHead,stat,empty,money,fmtDate,customerName,isApprover,renderModule,activeTab:()=>activeTab,renderLegacyInvoices:renderInvoicesLegacy};}
  function buildProductsContext(){return {state,pageHead,empty,money,num,statusBadge,renderModule,activeTab:()=>activeTab,renderDigitalLicenses,cloudProductsError:()=>cloudProductsError};}
  function buildCustomersContext(){return {state,pageHead,empty,money,num,statusBadge,fmtDate,customerDebt,activeSales,renderModule,activeTab:()=>activeTab};}
  function buildLicensesContext(){return {state,pageHead,empty,num,statusBadge,fmtDate,customerName,licenseComputedStatus,licenseRemainingDays,activeTab:()=>activeTab};}
  function renderCustomers(){return window.NuvexaCustomers?.render(buildCustomersContext())||renderCustomersLegacy();}
  function renderProducts(){return window.NuvexaProducts?.render(buildProductsContext())||renderProductsLegacy();}
  function renderOrders(){return window.NuvexaOrders?.renderOrders(buildOrdersContext())||renderOrdersLegacy();}
  function renderInvoices(){return window.NuvexaOrders?.renderInvoices(buildOrdersContext())||renderInvoicesLegacy();}
  function renderModule(id){return window.NuvexaAdmin?.renderModule(buildAdminContext(),id)}
  function rerender(){if(activeModule)renderModule(activeModule);else renderLauncher()}
  function renderDashboard(){
    const c=calculations(),alerts=derivedNotifications().slice(0,6),openOrders=state.orders.filter(o=>!['تم التسليم','ملغية'].includes(o.status)).length;
    const buyers=state.customers.filter(x=>!x.archived).length;
    const sellers=new Set((state.sellerSubmissions||[]).map(x=>normalizeEmail(x.sellerEmail)).filter(Boolean)).size;
    const pending=(state.sellerSubmissions||[]).filter(x=>x.status==='بانتظار المراجعة').length;
    const todaySales=activeSales().filter(i=>String(i.date||'').slice(0,10)===today()).reduce((s,i)=>s+num(i.total),0);
    const activeLicenses=(state.licenses||[]).filter(l=>licenseComputedStatus(l)==='فعال').length;
    const activities=(state.audit||[]).slice(0,6);
    return `${pageHead('الرئيسية','حالة المنصة في نظرة واحدة؛ كل بطاقة تنقلك إلى قسمها الطبيعي.')}${whatsappSetupBanner()}
    <div class="dashboard-six">
      <button class="dashboard-kpi" data-open-module="products"><div><span>إجمالي المنتجات والخدمات</span><strong>${state.products.filter(x=>!x.archived).length}</strong></div><i>📦</i></button>
      <button class="dashboard-kpi" data-open-module="orders"><div><span>الطلبات الجديدة والمفتوحة</span><strong>${openOrders}</strong></div><i>🛍️</i></button>
      <button class="dashboard-kpi" data-open-module="customers"><div><span>عدد المشترين</span><strong>${buyers}</strong></div><i>👤</i></button>
      <button class="dashboard-kpi" data-open-module="seller-submissions"><div><span>عدد البائعين</span><strong>${sellers}</strong></div><i>🤝</i></button>
      <button class="dashboard-kpi" data-open-module="reports"><div><span>مبيعات اليوم</span><strong>${money(todaySales)}</strong></div><i>💰</i></button>
      <button class="dashboard-kpi" data-open-module="seller-submissions"><div><span>منتجات بانتظار الاعتماد</span><strong>${pending}</strong></div><i>🔔</i></button>
    </div>
    <div class="content-grid" style="margin-top:16px">
      <section class="panel span-8"><div class="panel-head"><h3>مؤشرات التشغيل</h3><button class="btn btn-soft btn-sm" data-open-module="reports">فتح التقارير</button></div><div class="panel-body"><div class="total-line"><span>إجمالي المبيعات</span><strong>${money(c.revenue)}</strong></div><div class="total-line"><span>المبالغ المحصلة</span><strong>${money(c.collected)}</strong></div><div class="total-line"><span>ذمم المشترين</span><strong>${money(c.receivables)}</strong></div><div class="total-line"><span>التراخيص النشطة</span><strong>${activeLicenses}</strong></div></div></section>
      <section class="panel span-4"><div class="panel-head"><h3>آخر التنبيهات</h3><button class="btn btn-soft btn-sm" data-open-module="alerts">عرض الكل</button></div><div class="panel-body">${alerts.length?alerts.map(a=>`<div class="dashboard-activity-item"><span>${esc(a.title)}</span>${statusBadge(a.type)}</div>`).join(''):empty('assets/empty-states/empty-notifications.webp','لا توجد تنبيهات','كل شيء هادئ حاليًا.')}</div></section>
      <section class="panel span-12"><div class="panel-head"><h3>آخر نشاط داخل المنصة</h3></div><div class="panel-body">${activities.length?`<div class="dashboard-activity-list">${activities.map(a=>`<div class="dashboard-activity-item"><div><strong>${esc(a.action)}</strong><div class="muted">${esc(a.details||'')}</div></div><small>${esc(a.user||'النظام')} · ${fmtDate(a.date)}</small></div>`).join('')}</div>`:empty('assets/empty-states/empty-chat.webp','لا يوجد نشاط مسجل','سيظهر سجل العمليات هنا تلقائيًا.')}</div></section>
    </div>`}
  function renderSales(){if(activeTab==='سجل المبيعات')return renderSalesHistory();const subtotal=posCart.reduce((s,x)=>s+num(x.price)*num(x.qty),0);return `${pageHead('نقطة البيع','أضف المنتجات للسلة ثم أكمل الدفع. لا تُحسب المبيعات إلا بعد إنشاء الفاتورة.',`<button class="btn btn-soft" data-modal="product">＋ منتج جديد</button>`)}
    <div class="pos-layout"><section class="panel"><div class="panel-head"><h3>المنتجات المتاحة</h3><div class="searchbox" style="max-width:330px"><span>⌕</span><input id="posSearch" class="input" placeholder="ابحث عن منتج..." /></div></div><div class="panel-body">${state.products.filter(p=>!p.archived).length?`<div id="posProducts" class="product-grid">${productCards()}</div>`:empty('assets/products/product-placeholder.webp','لا توجد منتجات','أضف أول منتج، ثم أدخل رصيده من قسم المخزون.',`<button class="btn btn-gold" data-modal="product">إضافة منتج</button>`)}</div></section>
    <aside class="panel"><div class="panel-head"><h3>سلة البيع (${posCart.length})</h3><button class="btn btn-danger btn-sm" data-action="clear-cart">تفريغ</button></div><div class="panel-body"><div id="cartList" class="cart-list">${posCart.length?posCart.map(cartRow).join(''):`<div class="muted" style="text-align:center;padding:30px 0">السلة فارغة</div>`}</div><div class="cart-total"><div class="total-line"><span>الإجمالي</span><strong>${money(subtotal)}</strong></div><div class="total-line grand"><span>المطلوب</span><strong>${money(subtotal)}</strong></div><button class="btn btn-success" style="width:100%;margin-top:8px" data-action="checkout" ${subtotal<=0?'disabled':''}>إتمام البيع والدفع</button><button class="btn btn-soft" style="width:100%" data-action="create-order-from-cart" ${subtotal<=0?'disabled':''}>حفظ كطلب جديد</button></div></div></aside></div>`}
  function productCards(filter=''){const q=filter.toLowerCase();return state.products.filter(p=>!p.archived&&(!q||`${p.name} ${p.sku||''}`.toLowerCase().includes(q))).map(p=>{const digital=p.type==='digital',available=digital||num(p.stock)>0;return `<article class="product-card"><img src="${p.image||'assets/products/product-placeholder.webp'}" alt=""><div class="product-info"><strong>${esc(p.name)}</strong><small>${esc(p.size||p.unit||'')}</small><small>${digital?`منتج رقمي · ${num(p.deviceLimit)||1} جهاز`:`المتاح: ${num(p.stock)}`}</small><div class="price">${money(p.price)}</div><button class="btn btn-gold btn-sm" style="width:100%;margin-top:9px" data-add-cart="${p.id}" ${available?'':'disabled'}>＋ إضافة للسلة</button></div></article>`}).join('')}
  function cartRow(x){return `<div class="cart-row"><div><strong>${esc(x.name)}</strong><div class="muted" style="font-size:11px;margin-top:4px">${money(x.price)} × ${x.qty}</div></div><div><div class="qty"><button data-cart-dec="${x.productId}">−</button><strong>${x.qty}</strong><button data-cart-inc="${x.productId}">＋</button></div><button class="btn btn-danger btn-sm" style="margin-top:7px;width:100%" data-cart-remove="${x.productId}">حذف</button></div></div>`}
  function renderSalesHistory(){return `${pageHead('سجل المبيعات','كل فاتورة بيع تظهر مرة واحدة فقط في الإجماليات.',`<button class="btn btn-gold" data-module-tab="نقطة البيع">فتح نقطة البيع</button>`)}<section class="panel"><div class="panel-body">${state.salesInvoices.length?salesTable(state.salesInvoices):empty('assets/empty-states/empty-invoices.webp','لا توجد مبيعات بعد','أكمل أول عملية بيع من نقطة البيع.')}</div></section>`}
  function salesTable(list){return `<div class="table-wrap"><table class="table"><thead><tr><th>الرقم</th><th>التاريخ</th><th>العميل</th><th>الإجمالي</th><th>المدفوع</th><th>المتبقي</th><th>الحالة</th><th>إجراءات</th></tr></thead><tbody>${list.map(i=>`<tr><td><button class="btn btn-soft btn-sm" data-view-sale="${i.id}">${esc(i.number)}</button></td><td>${fmtDate(i.date)}</td><td>${esc(customerName(i.customerId))}</td><td>${money(i.total)}</td><td>${money(i.paid)}</td><td>${money(Math.max(0,num(i.total)-num(i.paid)))}</td><td>${statusBadge(i.status)}</td><td><div class="toolbar"><button class="btn btn-soft btn-sm" data-view-sale="${i.id}">عرض</button><button class="btn btn-gold btn-sm" data-modal="edit-sale" data-id="${i.id}">تعديل</button><button class="btn btn-soft btn-sm" data-print-sale="${i.id}">طباعة / PDF</button>${num(i.paid)<num(i.total)?`<button class="btn btn-success btn-sm" data-modal="sale-payment" data-id="${i.id}">تحصيل</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`}
  function renderOrdersLegacy(){const list=state.orders;return `${pageHead('الطلبات والتوصيلات','الطلب لا يؤثر على المبيعات أو المخزون قبل الاعتماد والتسليم.',`<button class="btn btn-gold" data-modal="order">＋ طلب جديد</button>`)}<div class="stat-grid">${stat('كل الطلبات',String(list.length),'📋')}${stat('بانتظار الاعتماد',String(list.filter(x=>x.status==='بانتظار الاعتماد').length),'⏳')}${stat('قيد التجهيز',String(list.filter(x=>x.status==='قيد التجهيز').length),'📦')}${stat('في الطريق',String(list.filter(x=>x.status==='في الطريق').length),'🚚')}</div><section class="panel" style="margin-top:16px"><div class="panel-body">${list.length?ordersTable(list):empty('assets/empty-states/empty-orders.webp','لا توجد طلبات بعد','أنشئ أول طلب وسيظهر هنا.',`<button class="btn btn-gold" data-modal="order">طلب جديد</button>`)}</div></section>`}
  function ordersTable(list){return `<div class="table-wrap"><table class="table"><thead><tr><th>الرقم</th><th>العميل</th><th>المنتجات</th><th>الإجمالي</th><th>موعد التوصيل</th><th>الحالة</th><th>إجراءات</th></tr></thead><tbody>${list.map(o=>`<tr><td>${esc(o.number)}</td><td>${esc(customerName(o.customerId))}</td><td>${(o.items||[]).map(x=>`${esc(x.name)} × ${x.qty}`).join('<br>')}</td><td>${money(o.total)}</td><td>${fmtDate(o.deliveryDate)}</td><td>${statusBadge(o.status)}</td><td><div class="toolbar">${o.status==='بانتظار الاعتماد'&&isApprover()?`<button class="btn btn-success btn-sm" data-approve-order="${o.id}">اعتماد</button>`:''}${o.approved&&!['تم التسليم','ملغية'].includes(o.status)?`<button class="btn btn-blue btn-sm" data-next-order="${o.id}">تحديث الحالة</button>`:''}<button class="btn btn-danger btn-sm" data-cancel-order="${o.id}">إلغاء</button></div></td></tr>`).join('')}</tbody></table></div>`}
  function buyerMatches(c){
    if(c.archived&&buyersAdminFilter!=='archived')return false;
    const debt=customerDebt(c.id),orders=activeSales().filter(i=>i.customerId===c.id),hasDigital=orders.some(i=>(i.items||[]).some(x=>x.nonStock||state.products.find(p=>p.id===x.productId)?.type==='digital'));
    if(buyersAdminFilter==='active'&&c.status==='موقوف')return false;
    if(buyersAdminFilter==='stopped'&&c.status!=='موقوف')return false;
    if(buyersAdminFilter==='buyers'&&!orders.length)return false;
    if(buyersAdminFilter==='digital'&&!hasDigital)return false;
    if(buyersAdminFilter==='none'&&orders.length)return false;
    if(buyersAdminFilter==='archived'&&!c.archived)return false;
    const q=buyersAdminSearch.trim().toLowerCase();
    return !q||`${c.name||''} ${c.phone||''} ${c.whatsapp||''} ${c.email||''} ${c.country||''}`.toLowerCase().includes(q)
  }
  function renderCustomersLegacy(){
    if(activeTab==='المتابعات')return renderFollowups();
    const all=state.customers||[],list=all.filter(buyerMatches);
    const orderCount=id=>activeSales().filter(i=>i.customerId===id).length;
    const totalSpent=id=>activeSales().filter(i=>i.customerId===id).reduce((n,i)=>n+num(i.total),0);
    const filters=[['all','الكل',all.filter(c=>!c.archived).length],['active','نشط',all.filter(c=>!c.archived&&c.status!=='موقوف').length],['stopped','موقوف',all.filter(c=>!c.archived&&c.status==='موقوف').length],['buyers','أجرى شراء',all.filter(c=>!c.archived&&orderCount(c.id)>0).length],['digital','اشترى خدمة رقمية',all.filter(c=>!c.archived&&activeSales().some(i=>i.customerId===c.id&&(i.items||[]).some(x=>x.nonStock||state.products.find(p=>p.id===x.productId)?.type==='digital'))).length],['none','لم يشترِ بعد',all.filter(c=>!c.archived&&orderCount(c.id)===0).length],['archived','المؤرشفون',all.filter(c=>c.archived).length]];
    const controls=`<div class="products-admin-toolbar"><div class="searchbox"><span>⌕</span><input id="buyersAdminSearch" class="input" value="${esc(buyersAdminSearch)}" placeholder="ابحث بالاسم أو الهاتف أو البريد..."></div><div class="catalog-view-switch"><button class="view-switch-btn ${buyersAdminView==='table'?'active':''}" data-buyers-view="table" title="جدول">▤</button><button class="view-switch-btn ${buyersAdminView==='cards'?'active':''}" data-buyers-view="cards" title="بطاقات">▦</button><button class="view-switch-btn ${buyersAdminView==='list'?'active':''}" data-buyers-view="list" title="قائمة">☰</button></div></div><div class="products-admin-filters">${filters.map(([id,label,count])=>`<button class="${buyersAdminFilter===id?'active':''}" data-buyers-filter="${id}">${label} <small>${count}</small></button>`).join('')}</div>`;
    let content='';
    if(!list.length)content=empty('assets/empty-states/empty-customers.webp','لا توجد نتائج','غيّر البحث أو الفلتر الحالي.');
    else if(buyersAdminView==='cards')content=`<div class="admin-products-grid">${list.map(c=>`<article class="admin-product-card"><div class="admin-product-card-body"><div style="display:flex;justify-content:space-between;gap:12px;align-items:center"><div><h3>${esc(c.name)}</h3><div class="muted">${esc(c.email||c.phone||'بدون بيانات اتصال')}</div></div>${statusBadge(c.status==='موقوف'?'موقوف':'نشط')}</div><div class="admin-product-meta"><span>${orderCount(c.id)} طلب</span><strong>${money(totalSpent(c.id))}</strong></div><div class="admin-product-meta"><span>المديونية</span><strong>${money(customerDebt(c.id))}</strong></div><div class="toolbar"><button class="btn btn-soft btn-sm" data-modal="customer" data-id="${c.id}">التفاصيل والتعديل</button><button class="btn btn-blue btn-sm" data-modal="followup" data-id="${c.id}">متابعة</button></div></div></article>`).join('')}</div>`;
    else if(buyersAdminView==='list')content=`<div class="admin-products-list">${list.map(c=>`<article class="admin-product-row"><div><strong>${esc(c.name)}</strong><div class="muted">${esc(c.email||c.phone||'—')}</div></div><span class="hide-mobile">${orderCount(c.id)} طلب</span><strong class="hide-mobile">${money(totalSpent(c.id))}</strong><div class="toolbar"><button class="btn btn-soft btn-sm" data-modal="customer" data-id="${c.id}">فتح</button></div></article>`).join('')}</div>`;
    else content=`<div class="table-wrap"><table class="table"><thead><tr><th>المشتري</th><th>الهاتف / البريد</th><th>الطلبات</th><th>إجمالي المشتريات</th><th>المديونية</th><th>الحالة</th><th>إجراءات</th></tr></thead><tbody>${list.map(c=>`<tr><td><strong>${esc(c.name)}</strong><div class="muted">${esc(c.country||c.classification||'')}</div></td><td>${esc(c.phone||'—')}<div class="muted">${esc(c.email||'')}</div></td><td>${orderCount(c.id)}</td><td>${money(totalSpent(c.id))}</td><td>${money(customerDebt(c.id))}</td><td>${statusBadge(c.status==='موقوف'?'موقوف':'نشط')}</td><td><div class="toolbar"><button class="btn btn-soft btn-sm" data-modal="customer" data-id="${c.id}">تفاصيل</button><button class="btn btn-blue btn-sm" data-modal="followup" data-id="${c.id}">متابعة</button><button class="btn btn-danger btn-sm" data-archive-customer="${c.id}">أرشفة</button></div></td></tr>`).join('')}</tbody></table></div>`;
    return `${pageHead('المشترون','ثلاث طرق عرض مع بحث وفلاتر سريعة، مع الحفاظ على كل بيانات العملاء والمتابعات الحالية.',`<button class="btn btn-gold" data-modal="customer">＋ تسجيل مشتري يدويًا</button>`)}<section class="panel"><div class="panel-body">${controls}${content}</div></section>`
  }
  function renderFollowups(){const items=state.customers.flatMap(c=>(c.followups||[]).map(f=>({...f,customerName:c.name,customerId:c.id}))).sort((a,b)=>new Date(b.date)-new Date(a.date));return `${pageHead('متابعات العملاء','تظل المتابعة ظاهرة حتى تسجيل نتيجتها.',`<button class="btn btn-gold" data-modal="followup">＋ متابعة</button>`)}<section class="panel"><div class="panel-body">${items.length?`<div class="table-wrap"><table class="table"><thead><tr><th>العميل</th><th>الموعد</th><th>النتيجة</th><th>الملاحظة</th><th>المستخدم</th></tr></thead><tbody>${items.map(f=>`<tr><td>${esc(f.customerName)}</td><td>${fmtDate(f.date)}</td><td>${statusBadge(f.result||'مفتوحة')}</td><td>${esc(f.note||'')}</td><td>${esc(f.user||'')}</td></tr>`).join('')}</tbody></table></div>`:empty('assets/empty-states/empty-customers.webp','لا توجد متابعات','أضف متابعة لعميل عند الحاجة.')}</div></section>`}
  function productAdminMatches(p){
    if(p.archived&&productsAdminFilter!=='archived')return false;
    if(productsAdminFilter==='physical'&&p.type==='digital')return false;
    if(productsAdminFilter==='digital'&&p.type!=='digital')return false;
    if(productsAdminFilter==='published'&&(p.showInStore===false||p.archived))return false;
    if(productsAdminFilter==='hidden'&&p.showInStore!==false)return false;
    if(productsAdminFilter==='archived'&&!p.archived)return false;
    const q=productsAdminSearch.trim().toLowerCase();
    return !q||`${p.name||''} ${p.sku||''} ${p.category||''} ${p.developerName||''}`.toLowerCase().includes(q)
  }
  function renderProductsLegacy(){
    const cloudNote=cloudProductsError?`<div class="platform-cloud-error">تعذر مزامنة المنتجات: ${esc(cloudProductsError)}</div>`:`<div class="submission-cloud-note"><i>☁️</i><div><strong>المنتجات مرتبطة بـ Supabase</strong><p>الإضافة والتعديل والأرشفة تُحفظ الآن في قاعدة البيانات السحابية.</p></div></div>`;
    if(activeTab==='التراخيص الرقمية')return renderDigitalLicenses();
    const list=state.products.filter(productAdminMatches),all=state.products||[];
    const filters=[['all','الكل',all.filter(p=>!p.archived).length],['physical','المنتجات',all.filter(p=>!p.archived&&p.type!=='digital').length],['digital','الخدمات الرقمية',all.filter(p=>!p.archived&&p.type==='digital').length],['published','المنشورة',all.filter(p=>!p.archived&&p.showInStore!==false).length],['hidden','المخفية',all.filter(p=>!p.archived&&p.showInStore===false).length],['archived','المؤرشفة',all.filter(p=>p.archived).length]];
    const controls=`<div class="products-admin-toolbar"><div class="searchbox"><span>⌕</span><input id="productsAdminSearch" class="input" value="${esc(productsAdminSearch)}" placeholder="ابحث بالاسم أو SKU أو التصنيف..."></div><div class="catalog-view-switch"><button class="view-switch-btn ${productsAdminView==='table'?'active':''}" data-products-view="table" title="جدول">▤</button><button class="view-switch-btn ${productsAdminView==='cards'?'active':''}" data-products-view="cards" title="بطاقات">▦</button><button class="view-switch-btn ${productsAdminView==='list'?'active':''}" data-products-view="list" title="قائمة">☰</button></div></div><div class="products-admin-filters">${filters.map(([id,label,count])=>`<button class="${productsAdminFilter===id?'active':''}" data-products-filter="${id}">${label} <small>${count}</small></button>`).join('')}</div>`;
    let content='';
    if(!list.length)content=empty('assets/products/product-placeholder.webp','لا توجد نتائج','غيّر البحث أو الفلتر، أو أضف منتجًا أو خدمة جديدة.',`<button class="btn btn-gold" data-modal="product">إضافة منتج أو خدمة</button>`);
    else if(productsAdminView==='cards')content=`<div class="admin-products-grid">${list.map(p=>`<article class="admin-product-card"><img src="${p.image||'assets/products/product-placeholder.webp'}" alt=""><div class="admin-product-card-body"><h3>${esc(p.name)}</h3><div class="admin-product-meta"><span>${p.type==='digital'?'خدمة رقمية':'منتج'}</span><strong>${money(p.price)}</strong></div><div class="admin-product-meta"><span>${p.type==='digital'?`${num(p.deviceLimit)||1} جهاز`:`المخزون ${num(p.stock)}`}</span><span>${p.showInStore===false?'مخفي':'منشور'}</span></div><div class="toolbar"><button class="btn btn-soft btn-sm" data-modal="product" data-id="${p.id}">تعديل</button><button class="btn btn-danger btn-sm" data-archive-product="${p.id}">أرشفة</button></div></div></article>`).join('')}</div>`;
    else if(productsAdminView==='list')content=`<div class="admin-products-list">${list.map(p=>`<article class="admin-product-row"><img src="${p.image||'assets/products/product-placeholder.webp'}" alt=""><div><strong>${esc(p.name)}</strong><div class="muted">${esc(p.sku||p.category||'بدون تصنيف')}</div></div><span class="hide-mobile">${p.type==='digital'?'خدمة رقمية':'منتج'}</span><strong class="hide-mobile">${money(p.price)}</strong><div class="toolbar"><button class="btn btn-soft btn-sm" data-modal="product" data-id="${p.id}">تعديل</button></div></article>`).join('')}</div>`;
    else content=`<div class="table-wrap"><table class="table"><thead><tr><th>الصورة</th><th>المنتج</th><th>النوع</th><th>سعر البيع</th><th>المخزون/الأجهزة</th><th>ظهور المتجر</th><th>إجراءات</th></tr></thead><tbody>${list.map(p=>`<tr><td><img src="${p.image||'assets/products/product-placeholder.webp'}" style="width:52px;height:52px;border-radius:12px;object-fit:cover"></td><td><strong>${esc(p.name)}</strong><div class="muted">${esc(p.sku||p.size||'')}</div></td><td>${statusBadge(p.type==='digital'?'رقمي':'عادي')}</td><td>${money(p.price)}</td><td>${p.type==='digital'?`${num(p.deviceLimit)||1} جهاز`:num(p.stock)}</td><td>${p.showInStore===false?statusBadge('مخفي'):statusBadge('معتمد')}</td><td><div class="toolbar"><button class="btn btn-soft btn-sm" data-modal="product" data-id="${p.id}">تعديل</button><button class="btn btn-danger btn-sm" data-archive-product="${p.id}">أرشفة</button></div></td></tr>`).join('')}</tbody></table></div>`;
    return `${pageHead('المنتجات والخدمات','ثلاث طرق عرض حقيقية مع بحث وفلاتر سريعة، وكل إجراء داخل قسمه.',`<button class="btn btn-gold" data-modal="product">＋ منتج أو خدمة</button>`)}${cloudNote}<section class="panel"><div class="panel-body">${controls}${content}</div></section>`
  }

  function renderInventory(){if(activeTab==='الحركات')return renderMovements();if(activeTab==='الدفعات')return renderBatches();const list=state.products.filter(p=>!p.archived&&p.type!=='digital');return `${pageHead('أرصدة المخزون','المنتجات الرقمية لا تدخل في أرصدة المخزون.',`<button class="btn btn-gold" data-modal="stock-adjust">＋ حركة مخزون</button><button class="btn btn-soft" data-modal="waste">تسجيل هالك</button>`)}<section class="panel"><div class="panel-body">${list.length?`<div class="table-wrap"><table class="table"><thead><tr><th>المنتج</th><th>الرصيد</th><th>المحجوز</th><th>المتاح</th><th>حد التنبيه</th><th>الحالة</th></tr></thead><tbody>${list.map(p=>{const r=reservedQty(p.id),a=num(p.stock)-r;return `<tr><td>${esc(p.name)}</td><td>${num(p.stock)}</td><td>${r}</td><td>${a}</td><td>${num(p.reorder)}</td><td>${a<=num(p.reorder)?statusBadge('مخزون منخفض'):statusBadge('معتمد')}</td></tr>`}).join('')}</tbody></table></div>`:empty('assets/empty-states/empty-inventory.webp','لا يوجد مخزون عادي بعد','أضف منتجًا عاديًا ثم سجل رصيده.')}</div></section>`}
  function renderMovements(){return `${pageHead('حركات المخزون','كل زيادة أو نقص مسجلة باسم المستخدم والسبب.',`<button class="btn btn-gold" data-modal="stock-adjust">＋ حركة جديدة</button>`)}<section class="panel"><div class="panel-body">${state.stockMovements.length?`<div class="table-wrap"><table class="table"><thead><tr><th>التاريخ</th><th>المنتج</th><th>النوع</th><th>الكمية</th><th>قبل</th><th>بعد</th><th>السبب</th><th>المستخدم</th></tr></thead><tbody>${state.stockMovements.map(m=>`<tr><td>${fmtDate(m.date)}</td><td>${esc(productName(m.productId))}</td><td>${statusBadge(m.type)}</td><td>${m.qty}</td><td>${m.before}</td><td>${m.after}</td><td>${esc(m.reason)}</td><td>${esc(m.user)}</td></tr>`).join('')}</tbody></table></div>`:empty('assets/empty-states/empty-inventory.webp','لا توجد حركات مخزون','ستظهر هنا كل حركة بعد تسجيلها.')}</div></section>`}
  function renderBatches(){const batches=state.products.flatMap(p=>(p.batches||[]).map(b=>({...b,productName:p.name})));return `${pageHead('دفعات المخزون','ترتيب الصرف حسب الأقرب انتهاءً FEFO.')}<section class="panel"><div class="panel-body">${batches.length?`<div class="table-wrap"><table class="table"><thead><tr><th>المنتج</th><th>رقم الدفعة</th><th>المتبقي</th><th>التكلفة</th><th>الإنتاج</th><th>الانتهاء</th></tr></thead><tbody>${batches.map(b=>`<tr><td>${esc(b.productName)}</td><td>${esc(b.lot||'—')}</td><td>${b.remaining}</td><td>${money(b.cost)}</td><td>${fmtDate(b.production)}</td><td>${fmtDate(b.expiry)}</td></tr>`).join('')}</tbody></table></div>`:empty('assets/empty-states/empty-inventory.webp','لا توجد دفعات','تُنشأ الدفعة عند اعتماد فاتورة شراء مرتبطة بمنتج.')}</div></section>`}
  function renderPurchases(){if(activeTab==='الموردون')return renderSuppliers();const list=state.purchaseInvoices;const debt=activePurchases().reduce((s,i)=>s+Math.max(0,num(i.total)-num(i.paid)),0);return `${pageHead('فواتير الشراء','الفاتورة المعتمدة غير المسددة تظهر كالتزام سالب.',`<button class="btn btn-gold" data-modal="purchase">＋ فاتورة شراء</button>`)}<div class="stat-grid">${stat('إجمالي المشتريات',calculations().purchaseTotal,'📦')}${stat('المبلغ المدفوع',calculations().purchasePaid,'💳')}${stat('المتبقي للموردين',`-${money(debt)}`,'📉','التزام سالب حتى السداد')}${stat('عدد الموردين',String(state.suppliers.filter(s=>!s.archived).length),'🏭')}</div><section class="panel" style="margin-top:16px"><div class="panel-body">${list.length?purchaseTable(list):empty('assets/empty-states/empty-invoices.webp','لا توجد فواتير شراء','أضف المورد ثم سجل أول فاتورة شراء.',`<button class="btn btn-gold" data-modal="purchase">فاتورة شراء</button>`)}</div></section>`}
  function purchaseTable(list){return `<div class="table-wrap"><table class="table"><thead><tr><th>الرقم</th><th>المورد</th><th>التاريخ</th><th>الإجمالي</th><th>المدفوع</th><th>المتبقي</th><th>الحالة</th><th>إجراءات</th></tr></thead><tbody>${list.map(i=>`<tr><td>${esc(i.number)}</td><td>${esc(supplierName(i.supplierId))}</td><td>${fmtDate(i.date)}</td><td>${money(i.total)}</td><td>${money(i.paid)}</td><td class="${num(i.total)-num(i.paid)>0?'negative':''}">${num(i.total)-num(i.paid)>0?'-':''}${money(Math.max(0,num(i.total)-num(i.paid)))}</td><td>${statusBadge(i.status)}</td><td><div class="toolbar"><button class="btn btn-gold btn-sm" data-modal="edit-purchase" data-id="${i.id}">تعديل</button>${i.status==='بانتظار الاعتماد'&&isApprover()?`<button class="btn btn-success btn-sm" data-approve-purchase="${i.id}">اعتماد</button>`:''}${i.approved&&num(i.paid)<num(i.total)&&canManageAccounts()?`<button class="btn btn-blue btn-sm" data-modal="purchase-payment" data-id="${i.id}">سداد</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`}
  function renderSuppliers(){const list=state.suppliers.filter(s=>!s.archived);return `${pageHead('الموردون','بيانات المورد ورصيده وفواتيره.',`<button class="btn btn-gold" data-modal="supplier">＋ مورد جديد</button>`)}<section class="panel"><div class="panel-body">${list.length?`<div class="table-wrap"><table class="table"><thead><tr><th>الاسم</th><th>الدولة</th><th>الهاتف</th><th>العملة</th><th>التقييم</th><th>المستحق له</th><th>إجراءات</th></tr></thead><tbody>${list.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.country||'—')}</td><td>${esc(s.phone||'—')}</td><td>${esc(s.currency||'TRY')}</td><td>${statusBadge(s.rating||'تحت التجربة')}</td><td class="negative">-${money(supplierDebtFor(s.id))}</td><td><button class="btn btn-soft btn-sm" data-modal="supplier" data-id="${s.id}">تعديل</button></td></tr>`).join('')}</tbody></table></div>`:empty('assets/empty-states/empty-customers.webp','لا يوجد موردون بعد','أضف أول مورد قبل تسجيل فاتورة شراء.',`<button class="btn btn-gold" data-modal="supplier">إضافة مورد</button>`)}</div></section>`}
  function renderInvoicesLegacy(){if(activeTab==='فواتير الشراء')return `${pageHead('فواتير الشراء','المعلقة تظهر بالسالب حتى السداد.')}<section class="panel"><div class="panel-body">${state.purchaseInvoices.length?purchaseTable(state.purchaseInvoices):empty('assets/empty-states/empty-invoices.webp','لا توجد فواتير شراء','')}</div></section>`;if(activeTab==='المرتجعات')return renderReturns();return `${pageHead('فواتير البيع','الإيراد من هذه الفواتير فقط، مرة واحدة لكل فاتورة.',`<button class="btn btn-gold" data-modal="manual-sale">＋ فاتورة يدوية</button><button class="btn btn-soft" data-open-module="sales">فتح نقطة البيع</button>`)}<section class="panel"><div class="panel-body">${state.salesInvoices.length?salesTable(state.salesInvoices):empty('assets/empty-states/empty-invoices.webp','لا توجد فواتير بعد','أكمل أول عملية بيع.')}</div></section>`}
  function renderReturns(){return `${pageHead('المرتجعات','المرتجع الجزئي أو الكلي يحتاج اعتمادًا.',`<button class="btn btn-gold" data-modal="return">＋ مرتجع</button>`)}<section class="panel"><div class="panel-body">${state.returns.length?`<div class="table-wrap"><table class="table"><thead><tr><th>الرقم</th><th>الفاتورة</th><th>المنتج</th><th>الكمية</th><th>الحالة</th><th>السبب</th></tr></thead><tbody>${state.returns.map(r=>`<tr><td>${esc(r.number)}</td><td>${esc(r.invoiceNumber)}</td><td>${esc(productName(r.productId))}</td><td>${r.qty}</td><td>${statusBadge(r.status)}</td><td>${esc(r.reason)}</td></tr>`).join('')}</tbody></table></div>`:empty('assets/empty-states/empty-invoices.webp','لا توجد مرتجعات','')}</div></section>`}
  function renderExpenses(){if(activeTab==='المتكررة')return renderRecurringExpenses();const list=state.expenses;return `${pageHead('المصروفات','تدخل الحسابات مباشرة، والتعديل أو الإلغاء للمحاسب والمدير فقط.',`<button class="btn btn-gold" data-modal="expense">＋ مصروف جديد</button>`)}<section class="panel"><div class="panel-body">${list.length?`<div class="table-wrap"><table class="table"><thead><tr><th>التاريخ</th><th>التصنيف</th><th>الوصف</th><th>المبلغ</th><th>طريقة الدفع</th><th>المستخدم</th><th>الحالة</th><th>إجراءات</th></tr></thead><tbody>${list.map(e=>`<tr><td>${fmtDate(e.date)}</td><td>${esc(e.category)}</td><td>${esc(e.description)}</td><td>${money(e.amount)}</td><td>${esc(e.method)}</td><td>${esc(e.user)}</td><td>${statusBadge(e.status||'معتمد')}</td><td>${isApprover()?`<button class="btn btn-danger btn-sm" data-cancel-expense="${e.id}">إلغاء</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:empty('assets/empty-states/empty-invoices.webp','لا توجد مصروفات','أضف أول مصروف عند حدوثه.',`<button class="btn btn-gold" data-modal="expense">مصروف جديد</button>`)}</div></section>`}
  function renderRecurringExpenses(){return `${pageHead('المصروفات المتكررة','تنبيه فقط ولا يتم التسجيل تلقائيًا.',`<button class="btn btn-gold" data-modal="recurring-expense">＋ إعداد متكرر</button>`)}<section class="panel"><div class="panel-body">${state.recurringExpenses.length?`<div class="table-wrap"><table class="table"><thead><tr><th>الاسم</th><th>التكرار</th><th>الموعد القادم</th><th>التصنيف</th><th>الحالة</th></tr></thead><tbody>${state.recurringExpenses.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.frequency)}</td><td>${fmtDate(r.nextDate)}</td><td>${esc(r.category)}</td><td>${statusBadge(r.active?'معتمد':'ملغية')}</td></tr>`).join('')}</tbody></table></div>`:empty('assets/empty-states/empty-notifications.webp','لا توجد مصروفات متكررة','')}</div></section>`}
  function renderChat(){if(activeTab==='مشكلات العمل')return renderIssues();return `${pageHead('شات الفريق','محادثة جماعية واحدة للمستخدمين الأربعة.')}<section class="panel chat-box"><div id="messages" class="messages">${state.messages.length?state.messages.map(m=>`<div class="message ${m.userId===sessionUser?'mine':''}"><strong>${esc(m.user)}</strong><div style="margin-top:6px;line-height:1.7">${esc(m.text)}</div><small>${new Date(m.date).toLocaleString('ar-EG')}</small></div>`).join(''):empty('assets/empty-states/empty-chat.webp','لا توجد محادثات بعد','اكتب أول رسالة للفريق.')}</div><form id="chatForm" class="chat-compose"><input id="chatInput" class="input" placeholder="اكتب رسالة للفريق..." required><button class="btn btn-gold">إرسال</button></form></section>`}
  function renderIssues(){return `${pageHead('مشكلات العمل','ملاحظات العملاء ومهام الفريق حتى الحل.',`<button class="btn btn-gold" data-modal="issue">＋ مشكلة عمل</button>`)}<section class="panel"><div class="panel-body">${state.workIssues.length?`<div class="table-wrap"><table class="table"><thead><tr><th>العنوان</th><th>الأولوية</th><th>المسؤول</th><th>الموعد</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>${state.workIssues.map(i=>`<tr><td>${esc(i.title)}</td><td>${statusBadge(i.priority)}</td><td>${esc(i.assignee||'غير محدد')}</td><td>${fmtDate(i.dueDate)}</td><td>${statusBadge(i.status)}</td><td>${i.status!=='تم الحل'?`<button class="btn btn-success btn-sm" data-close-issue="${i.id}">تم الحل</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:empty('assets/empty-states/empty-chat.webp','لا توجد مشكلات عمل','')}</div></section>`}
  function renderAlerts(){const actionItems=state.approvals.filter(a=>a.status==='بانتظار الاعتماد'),notes=derivedNotifications();if(activeTab==='تنبيهات فقط')return `${pageHead('تنبيهات فقط','تختفي من الواجهة بعد 48 ساعة عند معالجتها وتظل في السجل.')}<section class="panel"><div class="panel-body">${notes.length?`<div class="table-wrap"><table class="table"><thead><tr><th>النوع</th><th>العنوان</th><th>التفاصيل</th><th>إجراء</th></tr></thead><tbody>${notes.map(n=>`<tr><td>${statusBadge(n.type)}</td><td>${esc(n.title)}</td><td>${esc(n.details)}</td><td><button class="btn btn-soft btn-sm" data-dismiss-note="${n.id}">تم الاطلاع</button></td></tr>`).join('')}</tbody></table></div>`:empty('assets/empty-states/empty-notifications.webp','لا توجد إشعارات','')}</div></section>`;return `${pageHead('يتطلب إجراء','العناصر مرتبة حسب الأولوية ثم الأقدم.')}<section class="panel"><div class="panel-body">${actionItems.length?`<div class="table-wrap"><table class="table"><thead><tr><th>النوع</th><th>العنوان</th><th>منشئ الطلب</th><th>التاريخ</th><th>إجراءات</th></tr></thead><tbody>${actionItems.map(a=>`<tr><td>${statusBadge(a.type)}</td><td>${esc(a.title)}</td><td>${esc(a.createdBy)}</td><td>${fmtDate(a.date)}</td><td>${isApprover()?`<div class="toolbar"><button class="btn btn-success btn-sm" data-approve-item="${a.id}">اعتماد</button><button class="btn btn-danger btn-sm" data-reject-item="${a.id}">رفض</button></div>`:'بانتظار المراجع'}</td></tr>`).join('')}</tbody></table></div>`:empty('assets/empty-states/empty-notifications.webp','لا توجد اعتمادات معلقة','')}</div></section>`}
  function renderReportsLegacy(){const c=calculations();return `${pageHead('التقارير التشغيلية','الأرقام مأخوذة من مصدر واحد لكل نوع معاملة.',`<button class="btn btn-soft" data-action="export-sales">تصدير المبيعات CSV</button><button class="btn btn-soft" data-action="export-inventory">تصدير المخزون CSV</button>`)}<div class="stat-grid">${stat('إيرادات البيع',c.revenue,'📈')}${stat('تكلفة البضاعة المباعة',c.cogs,'📦')}${stat('المصروفات',c.expenses,'💳')}${stat('الربح التشغيلي',c.operatingProfit,'✅')}</div><div class="content-grid" style="margin-top:16px"><section class="panel span-6"><div class="panel-head"><h3>ملخص المبيعات</h3></div><div class="panel-body"><div class="total-line"><span>عدد الفواتير</span><strong>${activeSales().length}</strong></div><div class="total-line"><span>الإجمالي</span><strong>${money(c.revenue)}</strong></div><div class="total-line"><span>المحصل</span><strong>${money(c.collected)}</strong></div><div class="total-line"><span>المتبقي عند العملاء</span><strong>${money(c.receivables)}</strong></div></div></section><section class="panel span-6"><div class="panel-head"><h3>ملخص المخزون</h3></div><div class="panel-body"><div class="total-line"><span>عدد المنتجات</span><strong>${state.products.filter(p=>!p.archived).length}</strong></div><div class="total-line"><span>إجمالي الوحدات</span><strong>${state.products.reduce((s,p)=>s+num(p.stock),0)}</strong></div><div class="total-line"><span>قيمة المخزون بالتكلفة</span><strong>${money(state.products.reduce((s,p)=>s+num(p.stock)*num(p.cost),0))}</strong></div><div class="total-line"><span>منخفض المخزون</span><strong>${moduleCount('inventory')}</strong></div></div></section></div>`}
  function buildReportsContext(){return {state,activeTab:()=>activeTab,activeSales,calculations,pageHead,stat,money,num,fmtDate,statusBadge,empty,moduleCount,refresh:()=>renderModule('reports')}}
  function renderReports(){return window.NuvexaReports?.render(buildReportsContext())||renderReportsLegacy()}
  function renderAccounts(){if(!canViewAccounts())return empty('assets/empty-states/empty-invoices.webp','غير مصرح','لا تملك صلاحية المحاسبة.');if(!accountsUnlocked)return `${pageHead('المحاسبة والحسابات','هذا القسم محمي بكلمة مرور مستقلة.')}<section class="panel" style="max-width:520px;margin:70px auto"><div class="panel-body" style="padding:28px"><div style="text-align:center;font-size:54px">🔐</div><h2 style="text-align:center">فتح قسم المحاسبة</h2><p class="muted" style="text-align:center">أدخل كلمة مرور المحاسبة للمتابعة.</p><form id="accountUnlockForm"><div class="field"><label>كلمة مرور المحاسبة</label><input id="accountUnlockPassword" type="password" required></div><button class="btn btn-gold" style="width:100%;margin-top:14px">فتح الحسابات</button></form></div></section>`;const c=calculations();const manage=canManageAccounts();if(activeTab==='الخزنة والبنك')return renderTreasury(c,manage);if(activeTab==='القيود')return renderJournal(manage);if(activeTab==='التقارير')return renderAccountReports(c);return `${pageHead('المحاسبة والحسابات',manage?'صلاحية إدارة كاملة للحساب الإداري.':'عرض فقط.',manage?`<button class="btn btn-gold" data-modal="opening-balances">الأرصدة الافتتاحية</button><button class="btn btn-soft" data-modal="finance">حركة مالية</button><button class="btn btn-soft" data-modal="account-password">تغيير كلمة مرور المحاسبة</button>`:'')}<div class="stat-grid">${stat('الخزنة',c.cash,'💵')}${stat('الحساب البنكي',c.bank,'🏦')}${stat('ديون الموردين',`-${money(c.supplierDebt)}`,'📉')}${stat('صافي بعد الالتزامات',money(c.netAfterLiabilities),c.netAfterLiabilities<0?'⚠️':'✅')}</div><div class="content-grid" style="margin-top:16px"><section class="panel span-8"><div class="panel-head"><h3>فصل واضح بين الربح والسيولة</h3></div><div class="panel-body"><div class="total-line"><span>إيرادات البيع</span><strong>${money(c.revenue)}</strong></div><div class="total-line"><span>تكلفة البضاعة المباعة</span><strong>${money(c.cogs)}</strong></div><div class="total-line"><span>المصروفات</span><strong>${money(c.expenses)}</strong></div><div class="total-line"><span>الربح التشغيلي</span><strong class="${c.operatingProfit<0?'negative':'positive'}">${money(c.operatingProfit)}</strong></div><hr style="border:0;border-top:1px solid var(--line);margin:15px 0"><div class="total-line"><span>الأموال الفعلية بالخزنة والبنك</span><strong>${money(c.funds)}</strong></div><div class="total-line"><span>الفواتير المعلقة للموردين</span><strong class="negative">-${money(c.supplierDebt)}</strong></div><div class="total-line grand"><span>صافي المركز بعد الالتزامات</span><strong class="${c.netAfterLiabilities<0?'negative':'positive'}">${money(c.netAfterLiabilities)}</strong></div></div></section><section class="panel span-4"><div class="panel-head"><h3>نسبة تغطية الديون</h3></div><div class="panel-body"><div style="font-size:36px;font-weight:900;color:var(--gold2);text-align:center">${c.coverage.toFixed(1)}%</div><div class="progress" style="margin-top:15px"><span style="width:${c.coverage}%"></span></div><p class="muted" style="line-height:1.8">عند سداد الفاتورة ينخفض الدين ويُخصم السداد من الحساب المختار. إذا لم يكفِ الرصيد يظهر صافي المركز بالسالب.</p></div></section></div>`}
  function renderTreasury(c,manage){return `${pageHead('الخزنة والبنك','حساب نقدي واحد وحساب بنكي واحد.',manage?`<button class="btn btn-gold" data-modal="finance">＋ حركة مالية</button>`:'')}<div class="stat-grid">${stat('رصيد الخزنة',c.cash,'💵')}${stat('رصيد البنك',c.bank,'🏦')}${stat('إجمالي الأموال',c.funds,'💰')}${stat('المستحق للموردين',`-${money(c.supplierDebt)}`,'📉')}</div><section class="panel" style="margin-top:16px"><div class="panel-body">${state.finances.length?`<div class="table-wrap"><table class="table"><thead><tr><th>التاريخ</th><th>النوع</th><th>المبلغ</th><th>الطريقة</th><th>الشخص/الجهة</th><th>الملاحظة</th><th>المستخدم</th></tr></thead><tbody>${state.finances.map(f=>`<tr><td>${fmtDate(f.date)}</td><td>${statusBadge(f.type)}</td><td>${money(f.amount)}</td><td>${esc(f.method||'—')}</td><td>${esc(f.party||'—')}</td><td>${esc(f.note||'')}</td><td>${esc(f.user)}</td></tr>`).join('')}</tbody></table></div>`:empty('assets/empty-states/empty-invoices.webp','لا توجد حركات مالية مباشرة','')}</div></section>`}
  function renderJournal(manage){return `${pageHead('سجل القيود','القيود اليدوية لا تُعدّل؛ تُعكس بقيد عكسي.',manage?`<button class="btn btn-gold" data-modal="manual-journal">＋ قيد يدوي</button>`:'')}<section class="panel"><div class="panel-body">${state.journal.length?`<div class="table-wrap"><table class="table"><thead><tr><th>التاريخ</th><th>البيان</th><th>مدين</th><th>دائن</th><th>المبلغ</th><th>المرجع</th><th>إجراء</th></tr></thead><tbody>${state.journal.map(j=>`<tr><td>${fmtDate(j.date)}</td><td>${esc(j.description)}</td><td>${esc(j.debit)}</td><td>${esc(j.credit)}</td><td>${money(j.amount)}</td><td>${esc(j.reference||'—')}</td><td>${manage&&!j.reversed?`<button class="btn btn-danger btn-sm" data-reverse-journal="${j.id}">قيد عكسي</button>`:j.reversed?'معكوس':'—'}</td></tr>`).join('')}</tbody></table></div>`:empty('assets/empty-states/empty-invoices.webp','لا توجد قيود يدوية','القيود التلقائية لا تُستخدم لحساب الإيراد حتى لا يتكرر.')}</div></section>`}
  function renderAccountReports(c){return `${pageHead('التقارير المحاسبية','عرض شهري وسنوي وإمكانية التصدير.',`<button class="btn btn-soft" data-action="export-accounting">تصدير CSV</button>`)}<div class="stat-grid">${stat('الأرباح والخسائر',c.operatingProfit,'📊')}${stat('مديونيات العملاء',c.receivables,'👥')}${stat('مستحقات الموردين',`-${money(c.supplierDebt)}`,'🏭')}${stat('قيمة المخزون',state.products.reduce((s,p)=>s+num(p.stock)*num(p.cost),0),'📦')}</div>`}
  function buildSettingsContext(){return {state,activeTab:()=>activeTab,pageHead,empty,esc,fmtDate,statusBadge,currentUser,userAvatar,isApprover,isPlatformOwner,whatsappSetupBanner,renderPlatformUsersSettings,renderLegacy:renderSettingsLegacy,refresh:()=>renderModule('settings')}}
  function renderSettings(){return window.NuvexaSettings?.render(buildSettingsContext())||renderSettingsLegacy()}
  function renderSettingsLegacy(){
    if(activeTab==='المستخدمون والصلاحيات')return renderPlatformUsersSettings();
    if(activeTab==='النسخ الاحتياطية')return renderBackups();
    if(activeTab==='السجل الأمني')return renderAudit();
    const u=currentUser();
    const profile=`<section class="profile-card-premium">
      <div class="profile-photo-wrap"><img src="${userAvatar(u)}" alt="الصورة الشخصية"><span class="profile-photo-badge">✎</span></div>
      <div><h3>حساب الإدارة</h3><p>يمكنك رفع صورة الحساب أو تغييرها وستظهر في الهيدر داخل لوحة التحكم.</p></div>
      <div class="profile-actions"><label class="btn btn-gold" for="profileImageInput">رفع أو تغيير الصورة</label><input id="profileImageInput" type="file" accept="image/*" hidden><button class="btn btn-soft" data-action="remove-profile-photo" ${state.profileImages?.[u.id]?'':'disabled'}>إزالة الصورة المخصصة</button></div>
    </section>`;
    return `${pageHead('الإعدادات العامة','إعداداتك الشخصية وإعدادات النظام الحساسة.',`<button class="btn btn-soft" data-modal="admin-password">تغيير كلمة مرور الإدارة</button>${isApprover()?'<button class="btn btn-gold" data-modal="settings">تعديل إعدادات النظام والمتجر</button>':''}`)}${whatsappSetupBanner()}${profile}<section class="panel"><div class="panel-body"><div class="form-grid"><div><span class="muted">اسم النشاط</span><strong style="display:block;margin-top:7px">${esc(state.settings.shopName)}</strong></div><div><span class="muted">الشعار النصي</span><strong style="display:block;margin-top:7px">${esc(state.settings.tagline)}</strong></div><div><span class="muted">حد المخزون المنخفض</span><strong style="display:block;margin-top:7px">${state.settings.lowStock}</strong></div><div><span class="muted">حد الخصم الذي يحتاج اعتماد</span><strong style="display:block;margin-top:7px">${state.settings.discountApproval}%</strong></div><div><span class="muted">متابعة العميل الافتراضية</span><strong style="display:block;margin-top:7px">${state.settings.followUpDays} يوم</strong></div><div><span class="muted">نسخة احتياطية يومية</span><strong style="display:block;margin-top:7px">${state.settings.dailyBackup?'مفعلة':'متوقفة'}</strong></div><div><span class="muted">واجهة المتجر</span><strong style="display:block;margin-top:7px">${state.settings.storeEnabled?'مفعلة':'متوقفة'}</strong></div><div><span class="muted">رقم واتساب</span><strong style="display:block;margin-top:7px">${esc(state.settings.whatsappNumber||'لم يُضف بعد')}</strong></div></div></div></section>`
  }
  function renderPlatformUsersSettings(){
    if(!isPlatformOwner())return `${pageHead('المستخدمون والصلاحيات','إدارة الإيميلات متاحة لصاحب المنصة فقط.')}<section class="panel"><div class="panel-body">${empty('assets/empty-states/empty-notifications.webp','صلاحية غير متاحة','يمكن للشريك دخول لوحة الإدارة، لكن إضافة الإيميلات أو حذفها متاحة لصاحب المنصة فقط.')}</div></section>`;
    if(!platformUsersLoaded&&!platformUsersLoading)setTimeout(()=>loadPlatformUsers(),0);
    const rows=platformUsersCache.length?platformUsersCache.map(row=>`<tr><td><strong>${esc(row.display_name||'بدون اسم')}</strong>${row.protected?'<div class="muted">البريد الأساسي المحمي</div>':''}</td><td><span class="platform-user-email">${esc(row.email)}</span></td><td>${platformRoleBadge(row.role)}</td><td>${statusBadge(row.active?'فعال':'موقوف')}</td><td>${row.claimed===false?'<span class="badge b-gold">بانتظار أول دخول</span>':'<span class="badge b-green">مرتبط</span>'}</td><td>${fmtDate(row.created_at)}</td><td><div class="platform-user-actions"><button class="btn btn-soft btn-sm" data-platform-user-edit="${esc(row.email)}" ${row.protected?'disabled':''}>تعديل</button><button class="btn ${row.active?'btn-danger':'btn-success'} btn-sm" data-platform-user-toggle="${esc(row.email)}" ${row.protected?'disabled':''}>${row.active?'إيقاف':'تفعيل'}</button><button class="btn btn-danger btn-sm" data-platform-user-delete="${esc(row.email)}" ${row.protected?'disabled':''}>حذف</button></div></td></tr>`).join(''):`<tr><td colspan="7" class="muted" style="text-align:center;padding:28px">${platformUsersLoading?'جارٍ تحميل الإيميلات...':'لا توجد إيميلات مضافة.'}</td></tr>`;
    return `${pageHead('المستخدمون والصلاحيات','إدارة أدوار الحسابات مباشرة في Supabase، بما في ذلك الدعوات قبل أول تسجيل دخول.',`<button class="btn btn-gold" data-modal="platform-user">＋ إضافة بريد ودور</button><button class="btn btn-soft" data-platform-users-refresh>تحديث القائمة</button>`)}${platformAccessError?`<div class="platform-cloud-error"><strong>تعذر الاتصال بجدول الصلاحيات:</strong> ${esc(platformAccessError)}</div>`:''}<div class="platform-access-status"><i>☁</i><div><strong>الأدوار مرتبطة ببريد تسجيل Google</strong><p>المالك الأساسي: ${esc(PLATFORM_OWNER_EMAIL)}. يرى المتجر ولوحة البائع ولوحة الإدارة كاملة، ولا يمكن حذفه أو إيقافه.</p></div></div><section class="panel"><div class="panel-head"><h3>إيميلات وأدوار المنصة</h3><span class="badge b-blue">${platformUsersCache.length}</span></div><div class="panel-body"><div class="table-wrap"><table class="table"><thead><tr><th>الاسم</th><th>البريد</th><th>الدور</th><th>الحالة</th><th>الربط</th><th>تاريخ الإضافة</th><th>إجراء</th></tr></thead><tbody>${rows}</tbody></table></div></div></section>`
  }
  function renderUsersSettings(){return `${pageHead('أمان لوحة التحكم','الدخول موحّد بكلمة مرور واحدة قابلة للتغيير من الإعدادات.')}<section class="panel"><div class="panel-body"><p class="muted" style="line-height:1.9">لا توجد قائمة أسماء للمستخدمين. يتم فتح لوحة التحكم من خلال كلمة مرور الإدارة، ويمكن تغييرها من تبويب الإعدادات العامة.</p></div></section>`}
  function renderBackups(){return `${pageHead('النسخ الاحتياطية','نسخ يومية محلية وتصدير واستعادة يدوي.',`<button class="btn btn-gold" data-action="export-backup">تنزيل نسخة JSON</button><label class="btn btn-soft">استعادة نسخة<input id="importBackup" type="file" accept="application/json" hidden></label>${isApprover()?`<button class="btn btn-danger" data-action="reset-data">مسح كل البيانات</button>`:''}`)}<section class="panel"><div class="panel-body">${state.backups.length?`<div class="table-wrap"><table class="table"><thead><tr><th>التاريخ</th><th>النوع</th></tr></thead><tbody>${state.backups.map(b=>`<tr><td>${new Date(b.date).toLocaleString('ar-EG')}</td><td>${esc(b.type)}</td></tr>`).join('')}</tbody></table></div>`:empty('assets/empty-states/empty-notifications.webp','لا توجد نسخ محلية بعد','تُنشأ النسخة اليومية عند فتح النظام في يوم جديد.')}</div></section>`}
  function renderAudit(){return `${pageHead('السجل الأمني','الدخول والخروج والتغييرات الحساسة.')}<section class="panel"><div class="panel-body">${state.audit.length?`<div class="table-wrap"><table class="table"><thead><tr><th>التاريخ</th><th>المستخدم</th><th>الإجراء</th><th>التفاصيل</th></tr></thead><tbody>${state.audit.map(a=>`<tr><td>${new Date(a.date).toLocaleString('ar-EG')}</td><td>${esc(a.user)}</td><td>${esc(a.action)}</td><td>${esc(a.details||'')}</td></tr>`).join('')}</tbody></table></div>`:empty('assets/empty-states/empty-notifications.webp','السجل فارغ','')}</div></section>`}
  function bindDynamic(){window.NuvexaOrders?.bind(buildOrdersContext());window.NuvexaProducts?.bind(buildProductsContext());window.NuvexaCustomers?.bind(buildCustomersContext());window.NuvexaLicenses?.bind(buildLicensesContext());window.NuvexaReports?.bind(buildReportsContext());window.NuvexaSettings?.bind?.(buildSettingsContext());const unlock=$('#accountUnlockForm');if(unlock)unlock.addEventListener('submit',e=>{e.preventDefault();if($('#accountUnlockPassword').value===state.settings.accountPassword){accountsUnlocked=true;sessionSet('nuvexa_hub_accounts_unlocked','1');audit('فتح قسم المحاسبة');save();renderModule('accounts')}else toast('كلمة مرور المحاسبة غير صحيحة','error')});const ps=$('#posSearch');if(ps)ps.addEventListener('input',()=>{$('#posProducts').innerHTML=productCards(ps.value)});const cf=$('#chatForm');if(cf)cf.addEventListener('submit',e=>{e.preventDefault();const inp=$('#chatInput');if(!inp.value.trim())return;state.messages.push({id:uid('MSG'),date:now(),userId:sessionUser,user:currentUser().name,text:inp.value.trim()});audit('رسالة شات');save();renderModule('chat')})}
  function customerName(id){return state.customers.find(c=>c.id===id)?.name||(id==='CASH'?'عميل نقدي':'عميل غير مسجل')}
  function supplierName(id){return state.suppliers.find(s=>s.id===id)?.name||'—'}function productName(id){return state.products.find(p=>p.id===id)?.name||'—'}
  function customerDebt(id){return activeSales().filter(i=>i.customerId===id).reduce((s,i)=>s+Math.max(0,num(i.total)-num(i.paid)),0)}
  function supplierDebtFor(id){return activePurchases().filter(i=>i.supplierId===id).reduce((s,i)=>s+Math.max(0,num(i.total)-num(i.paid)),0)}
  function reservedQty(productId){const p=state.products.find(x=>x.id===productId);if(p?.type==='digital')return 0;return state.orders.filter(o=>o.approved&&!['تم التسليم','ملغية'].includes(o.status)).reduce((s,o)=>s+(o.items||[]).filter(x=>x.productId===productId&&!x.nonStock).reduce((a,x)=>a+num(x.qty),0),0)}
  function addStock(productId,qty,cost=0,batch={}){const p=state.products.find(x=>x.id===productId);if(!p)return;const before=num(p.stock);p.stock=before+num(qty);if(cost>0)p.cost=cost;p.batches=p.batches||[];if(qty>0)p.batches.push({id:uid('BAT'),qty:num(qty),remaining:num(qty),cost:num(cost),lot:batch.lot||'',production:batch.production||'',expiry:batch.expiry||'',date:now(),sourceInvoiceId:batch.sourceInvoiceId||''});state.stockMovements.unshift({id:uid('MOV'),date:now(),productId,type:'إضافة',qty:num(qty),before,after:p.stock,reason:batch.reason||'توريد/تعديل',user:currentUser().name})}
  function consumeStock(productId,qty,reason='بيع'){const p=state.products.find(x=>x.id===productId);if(!p||num(p.stock)<num(qty))return false;const before=num(p.stock);let need=num(qty),costTotal=0;const batches=(p.batches||[]).filter(b=>num(b.remaining)>0).sort((a,b)=>String(a.expiry||'9999').localeCompare(String(b.expiry||'9999')));for(const b of batches){if(need<=0)break;const take=Math.min(need,num(b.remaining));b.remaining-=take;need-=take;costTotal+=take*num(b.cost)}if(need>0){costTotal+=need*num(p.cost);need=0}p.stock=before-num(qty);state.stockMovements.unshift({id:uid('MOV'),date:now(),productId,type:'صرف',qty:-num(qty),before,after:p.stock,reason,user:currentUser().name});return{unitCost:num(qty)>0?costTotal/num(qty):num(p.cost)}}
  function reserveAvailable(items){return items.every(x=>{const p=state.products.find(p=>p.id===x.productId);if(x.nonStock||p?.type==='digital')return true;return p&&num(p.stock)-reservedQty(p.id)>=num(x.qty)})}
