    ids.forEach(id=>{const p=state.products.find(x=>x.id===id),oldQty=num(oldMap.get(id)),newQty=num(newMap.get(id)),delta=newQty-oldQty,oldLine=(inv.items||[]).find(x=>x.productId===id&&!x.nonStock);if(!p||!delta)return;if(delta>0){const c=consumeStock(id,delta,`فرق تعديل فاتورة ${inv.number}`);if(!c)throw new Error(`تعذر تحديث مخزون ${p.name}`);extraCost.set(id,c.unitCost)}else restoreSaleQuantity(id,-delta,num(oldLine?.unitCost)||num(p.cost),inv.number)});
    return newItems.map(x=>{const p=state.products.find(p=>p.id===x.productId);if(x.nonStock||p?.type==='digital')return {...x,nonStock:true,unitCost:num(x.unitCost)};const oldLine=(inv.items||[]).find(o=>o.productId===x.productId&&!o.nonStock),oldQty=Math.min(num(oldMap.get(x.productId)),num(x.qty)),added=Math.max(0,num(x.qty)-oldQty),oldCost=num(oldLine?.unitCost)||num(p?.cost),addedCost=num(extraCost.get(x.productId))||oldCost,unitCost=num(x.qty)>0?((oldQty*oldCost)+(added*addedCost))/num(x.qty):oldCost;return {...x,unitCost}});
