    if(type==='settings')set('الإعدادات العامة والمتجر',`<div class="form-grid"><div class="field"><label>اسم النشاط الداخلي</label><input name="shopName" value="${esc(state.settings.shopName)}" required></div><div class="field"><label>العبارة داخل الفواتير</label><input name="tagline" value="${esc(state.settings.tagline)}"></div><div class="field wide"><label>عنوان واجهة المتجر</label><input name="storeHeroTitle" value="${esc(state.settings.storeHeroTitle)}"></div><div class="field wide"><label>وصف واجهة المتجر</label><textarea name="storeHeroText">${esc(state.settings.storeHeroText)}</textarea></div><div class="field"><label>رقم واتساب لاستقبال طلبات العملاء</label><input name="whatsappNumber" value="${esc(state.settings.whatsappNumber)}" placeholder="مثال: 905xxxxxxxxx"><small>اكتب كود الدولة ثم الرقم من دون علامة + أو مسافات.</small></div><div class="field"><label>حد المخزون المنخفض</label><input name="lowStock" type="number" min="0" value="${state.settings.lowStock}"></div><div class="field"><label>متابعة العميل بعد أيام</label><input name="followUpDays" type="number" min="1" value="${state.settings.followUpDays}"></div><div class="field"><label>الخصم الذي يحتاج اعتماد %</label><input name="discountApproval" type="number" min="0" max="100" value="${state.settings.discountApproval}"></div><div class="field"><label>مرفق المصروف إلزامي من</label><input name="expenseReceiptThreshold" type="number" min="0" value="${state.settings.expenseReceiptThreshold}"></div><label><input name="storeEnabled" type="checkbox" ${state.settings.storeEnabled?'checked':''}> تفعيل واجهة المتجر</label><label><input name="dailyBackup" type="checkbox" ${state.settings.dailyBackup?'checked':''}> نسخة احتياطية يومية</label></div>`);
    if(type==='sale-payment'||type==='purchase-payment'){const inv=(type==='sale-payment'?state.salesInvoices:state.purchaseInvoices).find(x=>x.id===id);set(type==='sale-payment'?'تحصيل فاتورة بيع':'سداد فاتورة شراء',`<div class="panel" style="padding:13px;margin-bottom:14px"><div class="total-line"><span>الإجمالي</span><strong>${money(inv.total)}</strong></div><div class="total-line"><span>المدفوع</span><strong>${money(inv.paid)}</strong></div><div class="total-line"><span>المتبقي</span><strong>${money(num(inv.total)-num(inv.paid))}</strong></div></div><div class="form-grid"><div class="field"><label>المبلغ</label><input name="amount" type="number" min="0.01" max="${num(inv.total)-num(inv.paid)}" step="0.01" required></div><div class="field"><label>طريقة الدفع</label><select name="method"><option>نقدي</option><option>تحويل بنكي</option><option>بطاقة</option></select></div><div class="field"><label>رقم مرجعي</label><input name="reference"></div><div class="field"><label>صورة إيصال</label><input name="receipt" type="file" accept="image/*,application/pdf"></div></div>`)}
    if(type==='return')set('إنشاء مرتجع',`<div class="form-grid"><div class="field"><label>فاتورة البيع</label><select name="invoiceId" required><option value="">اختر الفاتورة</option>${optionList(state.salesInvoices,'id',i=>`${i.number} — ${customerName(i.customerId)}`)}</select></div><div class="field"><label>المنتج</label><select name="productId" required><option value="">اختر المنتج</option>${optionList(state.products,'id',p=>p.name)}</select></div><div class="field"><label>الكمية</label><input name="qty" type="number" min="0.01" step="0.01" required></div><div class="field"><label>حالة المنتج</label><select name="condition"><option>سليم</option><option>تالف</option></select></div><div class="field wide"><label>السبب</label><input name="reason" required></div></div>`);
    if(type==='edit-sale'){const inv=state.salesInvoices.find(x=>x.id===id);if(!inv){toast('الفاتورة غير موجودة','error');return}modalLines=(inv.items||[]).filter(x=>state.products.some(p=>p.id===x.productId)).map(x=>{const p=state.products.find(p=>p.id===x.productId);return{productId:x.productId,name:x.name||p?.name,qty:num(x.qty),price:num(x.price),nonStock:!!x.nonStock||p?.type==='digital',type:p?.type||x.type||'physical',deviceLimit:num(x.deviceLimit)||num(p?.deviceLimit)||1,unitCost:num(x.unitCost)}});set(`تعديل فاتورة البيع ${inv.number}`,invoiceEditHTML('sale',inv));setTimeout(initLineEditor,0)}
    if(type==='edit-purchase'){const inv=state.purchaseInvoices.find(x=>x.id===id);if(!inv){toast('الفاتورة غير موجودة','error');return}modalLines=(inv.items||[]).filter(x=>state.products.some(p=>p.id===x.productId)).map(x=>{const p=state.products.find(p=>p.id===x.productId);return{productId:x.productId,name:x.name||p?.name,qty:num(x.qty),price:num(x.cost),nonStock:false,type:p?.type||'physical',lot:x.lot||'',expiry:x.expiry||''}});set(`تعديل فاتورة الشراء ${inv.number}`,invoiceEditHTML('purchase',inv));setTimeout(initLineEditor,0)}
