      if(!['ملغية','مرفوضة','بانتظار الاعتماد'].includes(inv.status))inv.status=paid>=total?'مدفوعة':paid>0?'مدفوعة جزئيًا':'معلقة';
      inv.editHistory=inv.editHistory||[];inv.editHistory.unshift({date:now(),user:currentUser().name,reason:get('editReason'),before,after:{supplierId:inv.supplierId,date:inv.date,total:inv.total,extraCosts:inv.extraCosts,items:newItems.map(x=>({productId:x.productId,name:x.name,qty:x.qty,cost:x.cost}))}});
